   notes:['Provider quote timestamps determine freshness, not page refresh frequency.',
    'Polymarket US is reference-only with no funded positions.',
    'Favorites shown as market-implied confidence, not verified positive-EV wagers.',
    'Risk scales with available bankroll; an exceptionally small account can be considered for a single affordable contract, but only on independently verified profitable terms.',
    'DraftKings via SharpAPI is market data only; no sportsbook wagering API is available.',
    'DraftKings odds are background research only; no paired betting is enabled.'],
  };
}
export default {
  async fetch(request){
    const u=new URL(request.url),path=u.pathname;
    if(request.method==='GET'&&(path==='/'||path==='/index.html'))return new Response(HTML,{headers:{
      'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff',
      'referrer-policy':'no-referrer','x-frame-options':'DENY',
      'content-security-policy':"default-src 'none'; script-src 'self' 'unsafe-inline' 'wasm-unsafe-eval' https://cdn.jsdelivr.net; worker-src blob: 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self' https://cdn.jsdelivr.net https://huggingface.co https://*.hf.co; img-src 'self' data:; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"}});
    if(request.method==='GET'&&path==='/health'){
      const health={ok:true,service:'Kal Kings',uiServed:true,storageProvider:'Neon',buildTag:'sports-execution-v35',
        credentialsAvailable:requiredEnv(),liveExecutionEnabled:true,asOf:iso()};
      if(u.searchParams.get('probe')==='1'){
        try{health.probes=await memo('healthDiagnostics',20000,diagnostics);}
        catch{health.probes={error:'Diagnostic provider unavailable'};}
      }
      return reply(health);
    }
    if(path==='/cron/kalshi-solo'){
      if(request.method!=='POST')return error(405,'Method not allowed');
      let body;
      try {if(Number(request.headers.get('content-length'))>4096)return error(413,'Payload too large');
        const raw=await request.text();if(raw.length>4096)return error(413,'Payload too large');body=JSON.parse(raw);
      }catch{return error(400,'Invalid trigger payload');}
      if(!isNeonSoloTrigger({'x-neon-trigger-invocation-id':request.headers.get('x-neon-trigger-invocation-id')},body))
        return error(403,'Not an authorized Neon schedule trigger');
      try{const sports=await runSolo({invocationId:body.invocation_id,scheduledAt:body.data.scheduled_at});
          const crypto=await runCryptoCycle('schedule').catch(()=>({status:'UNAVAILABLE'}));
          // A public-page crawler sweep runs occasionally AFTER trade checks.
          // Timeouts never block the independent sports/crypto engines.
          if(new Date().getUTCMinutes()%15===0)
             await Promise.race([supplementalSportsResearch().catch(()=>null),
               new Promise(resolve=>setTimeout(resolve,1250))]);
          const reconciliation=await Promise.race([
            manualOrders.reconcilePending().catch(()=>({status:'UNAVAILABLE'})),
            new Promise(resolve=>setTimeout(()=>resolve({status:'DEFERRED'}),3500))
          ]);
          return reply({...sports,crypto,reconciliation});}
      catch{return error(503,'Kalshi automation unavailable');}
    }
    if(path==='/webhooks/tradingview'){
      if(request.method!=='POST')return error(405,'Method not allowed');
      try{
        if(Number(request.headers.get('content-length'))>2048)return error(413,'Alert too large');
        const raw=await request.text();if(raw.length>2048)return error(413,'Alert too large');
        return reply(await acceptTradingViewWebhook(JSON.parse(raw)));
      }catch{return error(400,'TradingView alert rejected');}
    }
    if(!path.startsWith('/api/'))return error(404,'Not found');
    if(!allowEnvToken(request))return error(401,'Invalid administrator token');
    if(request.method==='GET'&&path==='/api/session')return reply({authenticated:true,service:'Kal Kings'});
    if(request.method==='POST'&&path==='/api/automation/tick'){
      const scan=activeScanSlot(Date.now());
      try{return reply(await runSolo(scan))}
      catch{return error(503,'Trade scanner unavailable')}
    }
    try{
      if(request.method==='GET'&&path==='/api/state')return reply(await state());
      if(request.method==='GET'&&path==='/api/kalshi/status'){
        const [cryptoCycleStatus,scannerStatus,manualOrderHistory]=await Promise.all([
          getCryptoCycleStatus().catch(()=>({status:'UNAVAILABLE',scanned:0,candidates:0})),
          getScannerStatus().catch(()=>({status:'UNAVAILABLE'})),
          getManualOrders().catch(()=>[])]);
        return reply({cryptoCycleStatus,scannerStatus,manualOrderHistory,asOf:iso()});
      }
      if(request.method==='POST'&&path==='/api/research/refresh'){
        try{const report=await supplementalSportsResearch();
          return reply({provider:report.provider,observedAt:report.observedAt,characters:report.content.length,
            status:'RESEARCH_ONLY',sources:researchCrawlerPool.status()});}
        catch{return reply({status:'UNAVAILABLE',sources:researchCrawlerPool.status()},503);}
      }
      if(request.method==='GET'&&path==='/api/tradingview/alerts')return reply({alerts:await getTradingViewAlerts(),configured:await tradingViewEnabled()});
      if(request.method==='POST'&&path==='/api/tradingview/config')return reply(await setTradingViewSecret((await request.json()).passphrase));
                  if(request.method==='GET'&&path==='/api/kalshi/solo')return reply({orders:await getSoloOrders(),watches:await getPositionWatches(),settlements:await getBotSettlements()});
      if(request.method==='POST'&&path==='/api/kalshi/crypto-cycle')
        return reply(await runCryptoCycle('dashboard'));
      if(request.method==='GET'&&path==='/api/kalshi/manual/orders')return reply({orders:await getManualOrders()});
      if(request.method==='POST'&&path==='/api/kalshi/reconcile')
        return reply(await manualOrders.reconcilePending());
      if(request.method==='POST'&&path==='/api/kalshi/manual/preview')
        return reply(await manualOrders.preview(await request.json()));
      if(request.method==='POST'&&path==='/api/kalshi/manual/execute')
        return reply(await manualOrders.execute(await request.json()));
      if(request.method==='GET'&&path==='/api/kalshi/micro-test')return reply({test:await getOneTimeLiveTest()});
      if(request.method==='POST'&&path==='/api/kalshi/micro-test')return reply(await runOneTimeLiveTest(await request.json()));
            if(request.method==='POST'&&path==='/api/settings/odds-api'){
        const body=await request.json(); const key=str(body.key,128);
        if(key.length<8) return error(400,'Invalid odds API key');
        await saveSetting('odds_api_key',encryptSecret(key));cache.delete('draftkings');
        return reply({saved:true});
      }
      return error(404,'Route not found');
    }catch(e){
      const message=String(e?.message||'Error');
      const validation=/Invalid|not found|insufficient|uninitialized|Balance must/.test(message);
      // Never include provider response body, upstream keys, private key, SQL, or database URL.
      return error(validation?400:503,validation?message:'Service unavailable; check Neon Function configuration and upstream feeds');
    }
  }
};

kalshi_lifecycle.mjs:
/** Live Kalshi-only lifecycle. Processes only trades recorded as Kal Kings
 * solo orders; never automatically sells manual or DraftKings-hedged positions.
 * All read cash comes from Kalshi and settlement records are audit-only.
 */
import {cashAvailableForReinvestment,settlementEvidence,assessManagedExit,buildReductionOrder} from './kalshi_manager.mjs';
import {estimatedKalshiFee} from './engine.mjs';
const number=x=>Number(x);
export function makeKalshiLifecycle({fetchAccount,fetchSettlements,fetchMarket,sql,submit,createId,recordQuantQuote=async()=>{},getQuantHistory=async()=>[],quantExit=()=>({status:'INSUFFICIENT_HISTORY',action:'UNKNOWN'}),now=Date.now}){
 return async function monitor(){
  const account=await fetchAccount();
  const cash=cashAvailableForReinvestment(account);
  if(cash.status==='UNAVAILABLE'||account?.positionsComplete!==true)return {status:'ACCOUNT_UNAVAILABLE',freeCash:0,confirmedSettlements:0,exitsSubmitted:0,exitReceiptsConfirmed:0};
  const tracked=await sql("SELECT ticker,status,yes_filled::text AS yes_filled,no_filled::text AS no_filled,yes_price::text AS yes_price,no_price::text AS no_price FROM kal_kings_solo_orders WHERE status IN ('HEDGED','UNHEDGED','YES_FILLED','PARTIALLY_FILLED','UNCERTAIN','SUBMITTING') ORDER BY updated_at DESC LIMIT 100");
  let allSettlements=[],settlementFeed='VERIFIED';
  try{allSettlements=await fetchSettlements();}
  catch{settlementFeed='UNAVAILABLE';}
  const settled=Array.isArray(allSettlements)?allSettlements:[];
  const holdings=new Map((Array.isArray(account.holdings)?account.holdings:[]).map(p=>[p.ticker,p]));
  const result={status:'MONITORED',settlementFeed,freeCash:cash.available,holdings:account.holdings,positionsComplete:true,trackedPositions:tracked.length,confirmedSettlements:0,
    exitsSubmitted:0,exitReceiptsConfirmed:0,pendingReview:0};
  for(const trade of tracked){
    const proof=settlementEvidence(settled,trade.ticker);
    if(proof.status==='SETTLED'){
      await sql('INSERT INTO kal_kings_bot_settlements(ticker,settled_at) VALUES($1,$2::timestamptz) ON CONFLICT (ticker) DO NOTHING',[trade.ticker,proof.settledAt]);
      result.confirmedSettlements++;
      continue;
    }
    // Only a verified single uncovered YES position can be managed automatically.
    if(!['UNHEDGED','YES_FILLED'].includes(trade.status)){if(trade.status!=='HEDGED')result.pendingReview++;continue;}
    const desired=number(trade.yes_filled)-number(trade.no_filled);
    const actual=number(holdings.get(trade.ticker)?.position);
    const quantity=Math.floor(Math.min(desired,actual));
    if(!Number.isFinite(quantity)||quantity<1){result.pendingReview++;continue;}
    const prior=await sql('SELECT ticker,status,high_bid::text AS high_bid FROM kal_kings_position_watch WHERE ticker=$1',[trade.ticker]);
    if(prior.length&&['SUBMITTING','UNCERTAIN','CLOSED'].includes(prior[0].status)){if(prior[0].status!=='CLOSED')result.pendingReview++;continue;}
    let market;
    try{market=await fetchMarket(trade.ticker);}catch{result.pendingReview++;continue;}
    const age=now()-Date.parse(market?.observedAt||'');
    const bid=number(market?.yesBid),depth=number(market?.yesBidDepth);
    // Record only exchange-observed quotes. Monitoring never invents prices.
    if(Number.isFinite(bid)&&bid>0&&bid<1&&age>=0&&age<=3000){
      try{await recordQuantQuote(market);}catch{/* Missing journal cannot justify an order */}
    }
    // High-water mark stores the best observed executable bid (not last trade).
    const maxPrior=number(prior[0]?.high_bid??trade.yes_price);
    const peak=Number.isFinite(bid)?Math.max(maxPrior,bid):maxPrior;
    await sql(`INSERT INTO kal_kings_position_watch(ticker,position_side,entry_price,high_bid,status,updated_at)
      VALUES($1,'yes',$2,$3,'WATCHING',now()) ON CONFLICT(ticker) DO UPDATE
      SET high_bid=GREATEST(kal_kings_position_watch.high_bid,EXCLUDED.high_bid),updated_at=now()
      WHERE kal_kings_position_watch.status='WATCHING'`,[trade.ticker,String(trade.yes_price),String(peak)]);
    const decision=assessManagedExit({entryPrice:number(trade.yes_price),bidPrice:bid,highestBid:peak,availableDepth:depth,
      quantity,quoteAgeMs:age,estimatedExitFee:estimatedKalshiFee(quantity,bid),stopLossPercent:12,takeProfitPercent:20,trailingPercent:10});
    // Historical Monte Carlo exit is additional evidence; it cannot suppress
    // an already-triggered hard stop. Missing history means no MC signal.
    let mc={status:'INSUFFICIENT_HISTORY',action:'UNKNOWN'};
    if(decision.action!=='UNAVAILABLE'){
      try{const history=await getQuantHistory(trade.ticker);
        mc=quantExit({entryPrice:number(trade.yes_price),currentBid:bid,quantity,
          observations:history,entryFee:0,exitFee:estimatedKalshiFee(quantity,bid)});
      }catch{/* quant failure means existing stops remain operative */}
    }
    const mcSell=mc.status==='MODELED'&&mc.action==='SELL'&&
      Number.isFinite(Number(mc.exitAdvantageDollars))&&
      mc.exitAdvantageDollars>Math.max(.01,estimatedKalshiFee(quantity,bid));
    if(decision.action!=='SELL'&&!mcSell)continue;
    const orderId=createId();
    const claimed=await sql(`UPDATE kal_kings_position_watch SET status='SUBMITTING',exit_client_order_id=$2::uuid,updated_at=now()
      WHERE ticker=$1 AND status='WATCHING' RETURNING ticker`,[trade.ticker,orderId]);
    if(!claimed.length)continue;
    result.exitsSubmitted++;
    try{
      const request=buildReductionOrder({ticker:trade.ticker,direction:'yes',quantity,bidPrice:bid,clientOrderId:orderId});
      const response=await submit(request);
      const filled=number(response?.fill_count);
      const state=Number.isFinite(filled)&&filled>=quantity?'CLOSED':filled===0?'WATCHING':'UNCERTAIN';
      await sql('UPDATE kal_kings_position_watch SET status=$2,exit_fill_count=$3,exit_order_id=$4,updated_at=now() WHERE ticker=$1',
       [trade.ticker,state,Number.isFinite(filled)?String(filled):null,String(response?.order_id||'').slice(0,128)||null]);
      if(state==='CLOSED')result.exitReceiptsConfirmed++;
      else if(state==='UNCERTAIN')result.pendingReview++;
    }catch{
      // Network timeout can happen after a fill. Never submit a new exit
      // without an exchange receipt and explicit reconciliation.
      await sql('UPDATE kal_kings_position_watch SET status=$2,updated_at=now() WHERE ticker=$1',[trade.ticker,'UNCERTAIN']);
      result.pendingReview++;
    }
  }
  return result;
 };
}

kalshi_manager.mjs:
/** Kal Kings: managed Kalshi position and bankroll lifecycle. No market can be
 * timed at an objectively known peak. Decisions use actual bids, current free
 * cash, confirmed exchange holdings and configurable stop/trailing rules.
 * No fills or settlements are invented and no ledger credits are created.
 */
import {validPrice} from './engine.mjs';
const finite=n=>typeof n==='number'&&Number.isFinite(n);
const round=n=>Math.round((n+Number.EPSILON)*10000)/10000;

export function cashAvailableForReinvestment(exchange,{reserved=0}={}){
  // Latest exchange-reported *free* cash is the sole source of truth. The
  // settlement feed is a confirmation, never a separate balance credit.
  const balance=Number(exchange?.balance),hold=Number(reserved);
  if(!finite(balance)||balance<0||!finite(hold)||hold<0||hold>balance)
    return {available:0,status:'UNAVAILABLE'};
  const available=round(Math.max(0,balance-hold));
  return {available,status:available>0?'AVAILABLE':'UNFUNDED'};
}
export function settlementEvidence(settlements,ticker){
 const s=Array.isArray(settlements)?settlements.find(r=>r.ticker===ticker&&r.settled_time&&['yes','no','void','scalar'].includes(r.market_result)):null;
 return {status:s?'SETTLED':'NOT_CONFIRMED',settledAt:s?.settled_time||null,credited:false};
}
export function assessManagedExit({entryPrice,bidPrice,highestBid=entryPrice,availableDepth=0,quantity=0,quoteAgeMs=Infinity,
 estimatedExitFee=0,stopLossPercent=12,takeProfitPercent=20,trailingPercent=10}={}){
 const unavailable=reason=>({action:'UNAVAILABLE',reason});
 if(!validPrice(Number(entryPrice))||!validPrice(Number(bidPrice))||!validPrice(Number(highestBid))||
    !finite(Number(quantity))||quantity<=0||!finite(Number(estimatedExitFee))||estimatedExitFee<0||
    !finite(Number(quoteAgeMs))||quoteAgeMs<0||quoteAgeMs>3000||
    !finite(Number(availableDepth))||availableDepth<quantity||
    [stopLossPercent,takeProfitPercent,trailingPercent].some(x=>!finite(x)||x<=0||x>=100))return unavailable('STALE_ILLQUID_OR_INVALID');
 const peak=Math.max(Number(bidPrice),Number(highestBid)),bid=Number(bidPrice),entry=Number(entryPrice);
 const proceeds=(bid*quantity)-estimatedExitFee;
 const entryCost=entry*quantity;
 const net=round(proceeds-entryCost),netReturnPct=(proceeds/entryCost-1)*100;
 const peakPct=(peak/entry-1)*100;
 const drawdownPct=(1-bid/peak)*100;
 let reason=null;
 if(netReturnPct<=-stopLossPercent)reason='STOP_LOSS';
 else if(peakPct>=takeProfitPercent&&drawdownPct>=trailingPercent&&net>0)reason='TRAILING_PROFIT_EXIT';
 return {action:reason?'SELL':'HOLD',reason:reason||'NO_EXIT_SIGNAL',netProfitDollars:net,
  netReturnPercent:round(netReturnPct),peakBid:round(peak),drawdownPercent:round(drawdownPct),
  note:'No future price peak can be known; a stop or trailing exit may fail to fill at the quoted bid.'};
}
export function buildReductionOrder({ticker,direction,quantity,bidPrice,clientOrderId}){
 if(!/^[A-Z0-9_-]{4,128}$/.test(ticker||'')||!['yes','no'].includes(direction)||
    !Number.isInteger(quantity)||quantity<1||!validPrice(Number(bidPrice))||
    !/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(clientOrderId||''))throw RangeError('Invalid reduction request');
 // V2 book side yes=bid, no=ask (opposite exposure), with YES-scale price.
 return {ticker,client_order_id:clientOrderId,side:direction==='yes'?'ask':'bid',
  count:quantity.toFixed(2),price:(direction==='yes'?bidPrice:1-bidPrice).toFixed(4),
  reduce_only:true,time_in_force:'immediate_or_cancel',self_trade_prevention_type:'taker_at_cross',cancel_order_on_pause:true};
}
export function evaluateEntryTiming({candidate,sourceAgeMs,verifiedSettlement,freeCash}={}){
 if(!verifiedSettlement)return {action:'WAIT',reason:'UNVERIFIED_RULES'};
 if(!finite(Number(sourceAgeMs))||sourceAgeMs<0||sourceAgeMs>3000)return {action:'WAIT',reason:'STALE_MARKET'};
 const edge=Number(candidate?.netProfitDollars),cost=Number(candidate?.requiredDollars);
 if(!finite(edge)||edge<=0||!finite(cost)||cost<=0)return {action:'WAIT',reason:'NO_POSITIVE_NET_EDGE'};
 if(freeCash!=null&&(!finite(freeCash)||cost>freeCash+1e-8))return {action:'WAIT',reason:'INSUFFICIENT_FREE_CASH'};
 return {action:'QUALIFIED_NOW',reason:'POSITIVE_NET_EDGE_AT_CURRENT_QUOTE',estimatedReturnPercent:round(100*edge/cost)};
}

kalshi_solo.mjs:
/** Kal Kings independent Kalshi-only scanner.
 * Looks for a YES/NO complementary-price discount on ONE binary market.
 * It does not use DraftKings, Polymarket, fuzzy matching, or model-generated forecasts.
 * A positive two-sided quote is conditional, NOT a guaranteed realized profit:
 * the legs can fill separately and the book may move.
 */
import {cash,estimatedKalshiFee,quoteAge,validPrice} from './engine.mjs';
import {riskPolicy,adaptiveCapitalLimit} from './strategy.mjs';

const finite=n=>typeof n==='number'&&Number.isFinite(n);
export function findKalshiSoloCandidates(quotes,{balance,now=Date.now(),maxCandidates=10}={}){
  const free=Number(balance);
  if(!finite(free)||free<=0||!Array.isArray(quotes))return [];
  const policy=riskPolicy(free),out=[];
  for(const quote of quotes){
    const y=Number(quote.yesAsk),n=Number(quote.noAsk);
    const yd=Number(quote.yesDepth),nd=Number(quote.noDepth);
    if(!/^[A-Z0-9_-]{4,128}$/.test(quote.id||'')||!validPrice(y)||!validPrice(n)||!finite(yd)||!finite(nd)||yd<1||nd<1)continue;
    if(quoteAge(quote,now)>3000)continue;
    const firstLotFees=estimatedKalshiFee(1,y)+estimatedKalshiFee(1,n);
    const oneLotCost=y+n+firstLotFees;
    const unitProfit=1-oneLotCost;
    if(unitProfit<=1e-9)continue;
    const allowance=adaptiveCapitalLimit(policy,oneLotCost);
    const maxQuantity=Math.min(Math.floor(yd),Math.floor(nd),Math.floor(free/oneLotCost),Math.floor(allowance.budget/oneLotCost),50);
    if(maxQuantity<1)continue;
    let best=null;
    for(let count=1;count<=maxQuantity;count++){
      const fees=estimatedKalshiFee(count,y)+estimatedKalshiFee(count,n);
      const spent=count*(y+n)+fees;
      const net=count-spent;
      if(spent>free+1e-8||spent>allowance.budget+1e-8||net<=1e-9)continue;
      const orphanLoss=Math.max(count*y+estimatedKalshiFee(count,y),count*n+estimatedKalshiFee(count,n));
      // If the first leg fills alone, its entire cost can be lost. This risk
      // cannot exceed the bankroll or the adaptive capital allowance.
      if(orphanLoss>allowance.budget+1e-8)continue;
      best={id:`kalshi:${quote.id}`,marketTicker:quote.id,event:quote.event||quote.label||quote.id,
        source:'KALSHI_ONLY',strategy:'YES_NO_COMPLEMENT',count,yesPrice:y,noPrice:n,
        requiredDollars:Math.ceil((spent-1e-9)*10000)/10000,
        estimatedFeesDollars:Math.ceil((fees-1e-9)*10000)/10000,
        netProfitDollars:Math.round(net*10000)/10000,
        orphanLossDollars:cash(orphanLoss),quoteObservedAt:quote.observedAt,
        minimumTradeExceptionApplied:allowance.minimumTradeExceptionApplied,
        note:'Indicative positive two-sided spread; individual fills are not atomic. Trading may remain unhedged.'};
    }
    if(best)out.push(best);
  }
  return out.sort((a,b)=>b.netProfitDollars-a.netProfitDollars||a.marketTicker.localeCompare(b.marketTicker)).slice(0,maxCandidates);
}
export function kalshiSoloLegs(candidate,clientOrderIds){
  if(!candidate||candidate.source!=='KALSHI_ONLY'||!Array.isArray(clientOrderIds)||clientOrderIds.length!==2||clientOrderIds[0]===clientOrderIds[1])throw RangeError('Invalid independent Kalshi order plan');
  if(!Number.isInteger(candidate.count)||candidate.count<1||!validPrice(candidate.yesPrice)||!validPrice(candidate.noPrice)||candidate.yesPrice+candidate.noPrice>=1)throw RangeError('Invalid complementary prices');
  const ids=clientOrderIds;
  if(ids.some(id=>!/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(id)))throw RangeError('Invalid order identifiers');
  const base={ticker:candidate.marketTicker,count:candidate.count,action:'buy',type:'limit',
    time_in_force:'fill_or_kill',self_trade_prevention_type:'taker_at_cross',cancel_order_on_pause:true};
  return [{...base,side:'yes',yes_price_dollars:candidate.yesPrice.toFixed(4),client_order_id:ids[0]},
    {...base,side:'no',no_price_dollars:candidate.noPrice.toFixed(4),client_order_id:ids[1]}];
}
export function summarizeSoloOrders(orders=[]){
  const rows=Array.isArray(orders)?orders:[];
  return {totalAttempts:rows.length,fullyHedgedTrades:rows.filter(x=>x.status==='HEDGED'&&Number(x.yes_filled)>0&&Number(x.no_filled)>0).length,
    unhedgedPositions:rows.filter(x=>['UNHEDGED','UNCERTAIN'].includes(x.status)).length,
    notFilled:rows.filter(x=>x.status==='NOT_FILLED').length,
    realizedProfitDollars:null,note:'Executed legs and settlements must be reconciled; projected edge is not realized profit.'};
}

live_trade_test.mjs:
/** One-shot, tightly bounded live Kalshi connectivity trade.
 * This is an explicit integration test, not a profitability recommendation or
 * an automated strategy. Only one YES contract, never more than $0.03 at risk.
 */
import {normalizeKalshiBook,sweepAsks} from './quant.mjs';
import {estimatedKalshiFee} from './engine.mjs';
export const MICRO_TEST_MAX_OUTLAY=0.03;
export function planOneTimeMicroOrder({ticker,marketStatus,yesAsk,book,balance,positionsComplete}={}){
  const reject=reason=>({allowed:false,reason});
  if(!/^[A-Z0-9_-]{4,128}$/.test(ticker||'')||marketStatus!=='active')return reject('MARKET_NOT_ACTIVE');
  if(positionsComplete!==true)return reject('ACCOUNT_POSITIONS_INCOMPLETE');
  if(!Number.isFinite(balance)||balance<=0)return reject('CASH_UNAVAILABLE');
  if(!Number.isFinite(yesAsk)||yesAsk<=0||yesAsk>0.02)return reject('NO_LOW_COST_MARKET');
  let quotes;
  try{quotes=normalizeKalshiBook(book)}catch{return reject('INVALID_BOOK');}
  const sweep=sweepAsks(quotes.yesAsks,1);
  if(!sweep||!Number.isFinite(sweep.worstPrice)||sweep.worstPrice>0.02)return reject('NO_EXECUTABLE_CHEAP_ASK');
  if(Math.abs(sweep.worstPrice-yesAsk)>0.0001)return reject('QUOTE_DISAGREEMENT');
  const price=sweep.worstPrice,estimatedFee=estimatedKalshiFee(1,price);
  const fullCost=Math.ceil((price+estimatedFee-1e-9)*100)/100;
  if(fullCost>MICRO_TEST_MAX_OUTLAY+1e-8||fullCost>balance+1e-8)return reject('INSUFFICIENT_CASH_FOR_TEST');
  return {allowed:true,source:'KALSHI_ONLY',purpose:'ONE_TIME_LIVE_CONNECTIVITY_TEST',
    marketTicker:ticker,side:'bid',outcome:'yes',contracts:1,price,
    estimatedFeeDollars:estimatedFee,totalMaxDollars:fullCost,
    warning:'One-sided speculative test, not a hedged arbitrage and not validated positive expected value.'};
}
export function interpretMicroReceipt({post,confirmed}={}){
 const count=Number(post?.fill_count);
 if(!Number.isFinite(count)||count<0||count>1||typeof post?.order_id!=='string'||!post.order_id)return 'UNCERTAIN';
 if(count===0)return 'NOT_FILLED';
 const remote=confirmed?.order;
 if(remote?.order_id!==post.order_id||Number(remote.fill_count_fp)<1)return 'UNCERTAIN';
 return 'FILLED';
}

orders.mjs:
/** Kal Kings Kalshi-only automated hedge planner.
 * No DraftKings betting interface is available through SharpAPI.
 * A real order is considered only AFTER the user reports an accepted opposing
 * DraftKings wager and the exact market's rules have been independently reviewed.
 */
import {evaluatePair,quoteAge,validPrice,estimatedKalshiFee} from './engine.mjs';
import {riskPolicy,adaptiveCapitalLimit} from './strategy.mjs';

const fail=reason=>({accepted:false,reason});
export function buildKalshiHedgePlan({ticket,mapping,market,balance,now=Date.now()}={}){
  if(!ticket?.userConfirmed||ticket.status!=='open'||!mapping||ticket.pair_id!==mapping.id)
    return fail('UNCONFIRMED_OR_UNMATCHED_WAGER');
  if(mapping.kalshi_side!=='yes'||market?.id!==mapping.kalshi_ticker||ticket.selection!==mapping.dk_selection)
    return fail('CONTRACT_SIDE_OR_SELECTION_MISMATCH');
  const reviewed=Date.parse(mapping.reviewed_at??'');
  if(!/^sha256:[a-f0-9]{64}$/i.test(mapping.reviewed_rule_digest??'')||
      !Number.isFinite(reviewed)||reviewed>now||now-reviewed>7*86400000)
    return fail('REVIEW_EXPIRED');
  if(!validPrice(market?.yesAsk)||quoteAge(market,now)>3000||quoteAge(market,now)<0)
    return fail('MARKET_UNAVAILABLE_OR_STALE');
  const bank=Number(balance),depth=Math.floor(Number(market.yesDepth));
  if(!Number.isFinite(bank)||bank<=0||!Number.isFinite(depth)||depth<1)
    return fail('NO_AVAILABLE_BANKROLL_OR_DEPTH');
  const policy=riskPolicy(bank);
  const firstUnitCost=market.yesAsk+estimatedKalshiFee(1,market.yesAsk);
  const adaptive=adaptiveCapitalLimit(policy,firstUnitCost);
  const limit=adaptive.budget;
  const stake=Number(ticket.stake),odds=Number(ticket.odds);
  if(!Number.isFinite(stake)||stake<=0||!Number.isFinite(odds))return fail('INVALID_WAGER');
  let best=null;
  for(let count=1;count<=Math.min(depth,150);count++){
    const estimatedFee=estimatedKalshiFee(count,market.yesAsk);
    const expense=count*market.yesAsk+estimatedFee;
    if(expense>Math.min(limit,bank)+1e-9)break;
    let value;
    try{value=evaluatePair({contracts:count,kalshiAsk:market.yesAsk,dkStake:stake,dkAmerican:odds,feeUSD:estimatedFee,reviewed:true,sameResolution:true,dkAccepted:true},now);}catch{break;}
    if(!value.executableArbitrage)continue;
    if(!best||value.minimumProfit>best.minimumProfit)
      best={accepted:true,count,price:market.yesAsk,ticker:market.id,capitalRequired:expense,
        minimumProfit:value.minimumProfit,kalshiWinProfit:value.kalshiWins,dkWinProfit:value.draftKingsWins,
        estimatedKalshiFee:estimatedFee,minimumTradeExceptionApplied:adaptive.minimumTradeExceptionApplied,
        source:'User-confirmed DraftKings ticket + reviewed market rules'};
  }
  return best||fail('NO_POSITIVE_HEDGE_WITHIN_RISK_LIMIT');
}
export function kalshiV2Order({ticker,count,yesPrice,clientOrderId}){
  if(!/^[A-Z0-9_-]{4,128}$/i.test(ticker)||!Number.isInteger(count)||count<1||
    !validPrice(yesPrice)||!/^[0-9a-f-]{36}$/i.test(clientOrderId))throw Error('Invalid Kalshi order');
  return {ticker,client_order_id:clientOrderId,side:'bid',count:count.toFixed(2),
    price:Number(yesPrice).toFixed(4),time_in_force:'fill_or_kill',
    self_trade_prevention_type:'taker_at_cross',cancel_order_on_pause:true};
}

crypto_candidate.mjs:
/** These boosts are decision confidence points, NOT statistically measured win probabilities. */
export function cryptoConfidenceScore(modeledWinProbability,agreeingSources){
 const p=Number(modeledWinProbability),n=Number(agreeingSources);
 const bonusPoints=n===7?30:n===6?20:n===5?15:n===4?10:0;
 if(!Number.isFinite(p)||p<=0||p>=1)return {scorePercent:null,bonusPoints,tradeEligible:false};
 const scorePercent=Number(Math.min(100,p*100+bonusPoints).toFixed(2));
 return {scorePercent,bonusPoints,tradeEligible:n>=5&&scorePercent>=70};
}

export function selectCryptoIdea(signal,{now=Date.now()}={}){
 if(!signal||String(signal.symbol||'').toUpperCase()==='BTC'||!['UP','DOWN'].includes(signal.direction)||!signal.marketTicker)return null;
 const n=Number(signal.agreeingSources),fraction=n===7?.4:n===6?.3:n===5?.2:0;
 if(!fraction||Number(signal.reference?.sourceCount)<5||
    signal.reference?.exactBenchmarkReference!==true||
    !(Number(signal.reference?.referencePrice)>0)||
    !Number.isFinite(Number(signal.reference?.referencePrice)))return null;
 const model=signal.model,p=Number(signal.modeledWinProbability);
 const confidence=cryptoConfidenceScore(p,n);
 const age=now-Date.parse(model?.observedAt||'');
 if(model?.status!=='ESTIMATED'||Number(model.trials)<2500||
    !confidence.tradeEligible||age<0||age>30000)return null;
 const ticker=signal.marketTicker;
 if(!ticker.startsWith('KX'+signal.symbol+'15M-')||signal.market?.ticker!==ticker)return null;
 return {id:'crypto:'+ticker,eventKey:ticker.split('-').slice(0,2).join('-'),
  strategy:'CRYPTO_DIRECTIONAL_CONSENSUS',symbol:signal.symbol,
  side:signal.direction==='DOWN'?'no':'yes',market:{ticker},
  probability:p,model,agreeingSources:n,allocationFraction:fraction,
  confidenceScorePercent:confidence.scorePercent,consensusBonusPoints:confidence.bonusPoints,
  referencePrice:Number(signal.reference.referencePrice),referenceVerified:true,
  sourceVerified:true,marketMatchVerified:true,updatedAt:signal.updatedAt};
}

export function rankCryptoCandidates(signals,{now=Date.now(),max=6}={}){
 return (Array.isArray(signals)?signals:[]).map(signal=>selectCryptoIdea(signal,{now}))
  .filter(Boolean)
  .sort((a,b)=>b.agreeingSources-a.agreeingSources||b.probability-a.probability)
  .slice(0,Math.max(1,Math.min(12,max)));
}

crypto_trade_model.mjs:
import {seeded} from './engine.mjs';
export function runCryptoMonteCarlo({symbol,spotPrice,referencePrice,minutesRemaining,observedAt,volatilityPct=.35,now=Date.now(),trials=2500}={}){
 if(!referencePrice||!spotPrice)return {status:'UNVERIFIED_REFERENCE'};
 const age=now-Date.parse(observedAt);
 if(age<0||age>30000)return {status:'STALE_RESEARCH'};
 const price=Number(spotPrice),reference=Number(referencePrice),minutes=Number(minutesRemaining);
 if(!['ETH','SOL','XRP','DOGE','ADA'].includes(symbol)||
    !Number.isFinite(price)||price<=0||!Number.isFinite(reference)||reference<=0||
    !Number.isFinite(minutes)||minutes<=0||minutes>15||
    !Number.isInteger(trials)||trials<100||trials>20000)
   return {status:'UNVERIFIED_REFERENCE'};
 const rng=seeded(17),normal=()=>{
  const x=Math.max(1e-12,rng()),y=rng();
  return Math.sqrt(-2*Math.log(x))*Math.cos(2*Math.PI*y);
 };
 const vol=Number(volatilityPct);
 if(!Number.isFinite(vol)||vol<0||vol>25)return {status:'UNVERIFIED_VOLATILITY'};
 const sigma=Math.max(.003,vol/100)*Math.sqrt(minutes/5),gap=Math.log(price/reference);
 let wins=0;
 for(let i=0;i<trials;i++)if(gap+sigma*normal()+.0015*normal()>=0)wins++;
 const p=(wins+.5)/(trials+1),error=1.645*Math.sqrt(p*(1-p)/trials);
 return {status:'ESTIMATED',trials,yesProbability:p,
   lowerYesProbability:Math.max(0,p-error),upperYesProbability:Math.min(1,p+error),
   observedAt,validUntil:new Date(Date.parse(observedAt)+30000).toISOString(),
   benchmark:'SPOT_PROXY_NOT_CF_BENCHMARKS',historicalEvidence:'SECONDARY'};
}

directional_lifecycle.mjs:
/** Manages ONLY Kal Kings' own confirmed directional orders. Never touches other holdings. */
import {estimatedKalshiFee} from './engine.mjs';
import {normalizeKalshiBook} from './quant.mjs';
import {assessManagedExit,buildReductionOrder} from './kalshi_manager.mjs';
import {adaptiveExitThresholds,bidVolatilityPct} from './strategy_optimizer.mjs';
const finite=n=>Number.isFinite(Number(n));
const marketAge=(q,now)=>now-Date.parse(q?.observedAt||'');
export function makeDirectionalLifecycle({
 sql,fetchMarket,fetchOrderbook,fetchSettlements,submit,createId,
 getBidHistory=async()=>[],recordQuote=async()=>{},now=Date.now
}){
 return async function monitor(account={}){
  if(account.status!=='MONITORED'||account.positionsComplete!==true||!Array.isArray(account.holdings))
    return {status:'ACCOUNT_UNAVAILABLE',pendingReview:0,exitsSubmitted:0};
  const trades=await sql(`SELECT ticker,side,status,contracts::text AS contracts,
    filled_count::text AS filled_count,entry_price::text AS entry_price,
    high_bid::text AS high_bid,modeled_probability::text AS modeled_probability,event_key
    FROM kal_kings_directional_orders
    WHERE status IN ('FILLED','PARTIALLY_FILLED','SUBMITTING','UNCERTAIN',
      'EXIT_SUBMITTING','EXIT_UNCERTAIN')
    ORDER BY updated_at DESC LIMIT 30`);
  let settled=[];
  try{settled=await fetchSettlements()}catch{/* A missing settlement feed does not justify an exit. */}
  const holdings=new Map(account.holdings.map(p=>[p.ticker,Number(p.position)]));
  const out={status:'MONITORED',trackedPositions:trades.length,pendingReview:0,
    exitsSubmitted:0,exitReceiptsConfirmed:0,confirmedSettlements:0};
  for(const trade of trades){
   const evidence=(Array.isArray(settled)?settled:[]).find(x=>
      x.ticker===trade.ticker&&x.settled_time&&['yes','no','void','scalar'].includes(x.market_result));
   if(evidence){
     await sql(`UPDATE kal_kings_directional_orders SET status='SETTLED',
       settled_at=$2::timestamptz,updated_at=now()
       WHERE ticker=$1 AND status NOT IN ('SETTLED','CLOSED')`,
       [trade.ticker,evidence.settled_time]);
     out.confirmedSettlements++;continue;
   }
   if(!['FILLED','PARTIALLY_FILLED'].includes(trade.status)){out.pendingReview++;continue;}
   const count=Math.floor(Number(trade.filled_count)),signedHeld=holdings.get(trade.ticker);
   const held=trade.side==='no'?-signedHeld:signedHeld;
   // Exact ticker and confirmed Kalshi exposure are both required.
   if(!Number.isInteger(count)||count<1||!finite(held)||held<count){
     out.pendingReview++;continue;
   }
   let market,book;
   try{
     [market,book]=await Promise.all([fetchMarket(trade.ticker),fetchOrderbook(trade.ticker)]);
     book=normalizeKalshiBook(book);
   }catch{continue;}
   if(market?.id!==trade.ticker||!['open','active'].includes(market.status)||
     !finite(marketAge(market,now()))||marketAge(market,now())<0||
     marketAge(market,now())>3000)continue;
   const levels=trade.side==='no'?book.noBids:book.yesBids;
   const best=levels?.[0];
   if(!best||!finite(best.quantity)||best.quantity<count)continue;
   const bid=Number(best.price);
   if(!finite(bid)||bid<=0||bid>=1)continue;
   const prior=Number(trade.high_bid??trade.entry_price);
   const peak=Math.max(bid,Number.isFinite(prior)?prior:bid);
   await sql(`UPDATE kal_kings_directional_orders
      SET high_bid=GREATEST(COALESCE(high_bid,0),$2::numeric),updated_at=now()
      WHERE ticker=$1 AND status IN ('FILLED','PARTIALLY_FILLED')`,[trade.ticker,String(peak)]);
   try{await recordQuote({...market,yesBid:bid})}catch{/* Journal is optional for protective exits. */}
   let historical=[];
   try{historical=await getBidHistory(trade.ticker)}catch{}
   const observedVolatility=bidVolatilityPct(historical);
   const thresholds=adaptiveExitThresholds({volatilityPct:observedVolatility??5,
     confidence:Number(trade.modeled_probability)});
   const decision=assessManagedExit({entryPrice:Number(trade.entry_price),
     bidPrice:bid,highestBid:peak,availableDepth:best.quantity,
     quantity:count,quoteAgeMs:marketAge(market,now()),
     estimatedExitFee:estimatedKalshiFee(count,bid),...thresholds});
   if(decision.action!=='SELL')continue;
   const id=createId();
   const locked=await sql(`UPDATE kal_kings_directional_orders
      SET status='EXIT_SUBMITTING',exit_client_order_id=$2::uuid,updated_at=now()
      WHERE ticker=$1 AND status IN ('FILLED','PARTIALLY_FILLED') RETURNING ticker`,[trade.ticker,id]);
   if(!locked.length)continue;
   out.exitsSubmitted++;
   let status='EXIT_UNCERTAIN',orderId=null,filled=0;
   try{
     const reduce=buildReductionOrder({ticker:trade.ticker,direction:trade.side,
       quantity:count,bidPrice:bid,clientOrderId:id});
     const receipt=await submit(reduce);
     const n=Number(receipt?.fill_count);
     orderId=typeof receipt?.order_id==='string'?receipt.order_id.slice(0,128):null;
     filled=Number.isFinite(n)&&n>=0?n:0;
     status=!Number.isFinite(n)?'EXIT_UNCERTAIN':
       n>=count?'CLOSED':n===0?'FILLED':'EXIT_UNCERTAIN';
   }catch{/* A timeout may follow actual execution. Never retry an uncertain exit. */}
   await sql(`UPDATE kal_kings_directional_orders SET status=$2,
     exit_order_id=$3,exit_filled_count=$4::numeric,updated_at=now() WHERE ticker=$1`,
     [trade.ticker,status,orderId,String(filled)]);
   if(status==='CLOSED')out.exitReceiptsConfirmed++;
   if(status==='EXIT_UNCERTAIN')out.pendingReview++;
  }
  return out;
 };
}

directional_runner.mjs:
/**
 * Bounded Kalshi directional execution for verified live-game value.
 * Deliberately independent of the two-leg YES/NO arbitrage worker.
 * Submitted orders are idempotent, FOK, and marked uncertain on timeouts.
 */
import {estimatedKalshiBuyDebit} from './engine.mjs';
import {normalizeKalshiBook} from './quant.mjs';
import {assessKalshiValue} from './strategy_optimizer.mjs';
import {assessAlreadyExceededTotal} from './total_strategy.mjs';
import {planLateGameOrder} from './sports_allocation.mjs';
import {cryptoConfidenceScore} from './crypto_candidate.mjs';
const validTicker=t=>/^[A-Z0-9_-]{4,128}$/.test(t||'');
const age=(v,now)=>now-Date.parse(v||'');
/**
 * Keep the official order book as primary. If its side is empty, use the
 * same fresh market endpoint's displayed ask and ask-size only when valid.
 * This allows a bounded FOK attempt without inventing executable liquidity.
 */
export function resolveExecutableAskBook(book,market,side,now=Date.now()){
 const empty={yesBids:[],noBids:[],yesAsks:[],noAsks:[]};
 const normalized=book&&typeof book==='object'?{
   yesBids:Array.isArray(book.yesBids)?book.yesBids:[],
   noBids:Array.isArray(book.noBids)?book.noBids:[],
   yesAsks:Array.isArray(book.yesAsks)?book.yesAsks:[],
   noAsks:Array.isArray(book.noAsks)?book.noAsks:[]
 }:empty;
 if(!['yes','no'].includes(side))return {book:normalized,source:null};
 const field=side==='yes'?'yesAsks':'noAsks';
 if(normalized[field].length)return {book:normalized,source:'ORDERBOOK'};
 const observed=Date.parse(market?.observedAt||'');
 const price=Number(side==='yes'?market?.yesAsk:market?.noAsk);
 const quantity=Number(side==='yes'?market?.yesDepth:market?.noDepth);
 const ageMs=now-observed;
 if(!['active','open'].includes(market?.status))
   return {book:normalized,source:null,reason:'FRESH_MARKET_NOT_OPEN'};
 if(!Number.isFinite(ageMs)||ageMs<0||ageMs>3000)
   return {book:normalized,source:null,reason:'STALE_MARKET_QUOTE'};
 const reasons=[];
 if(!Number.isFinite(price)||price<=0||price>=1)reasons.push('ASK_PRICE_INVALID_OR_AT_BOUNDARY');
 if(!Number.isFinite(quantity)||quantity<1)reasons.push('NO_DISPLAYED_ASK_SIZE');
 if(reasons.length)return {book:normalized,source:null,reason:reasons.join('_AND_')};
 return {book:{...normalized,[field]:[{price:Math.round(price*10000)/10000,quantity}]},
   source:'MARKET_TOP_OF_BOOK',reason:null};
}
export function makeDirectionalRunner({sql,fetchMarket,fetchOrderbook,fetchFeeSchedule,
 fetchFinalConsensus,submit,createId,now=Date.now}){
 return async function run({ideas=[],account}={}){
  const clock=now();
  if(account?.status!=='VERIFIED'||account?.positionsComplete!==true||
    !Number.isFinite(Number(account?.balance))||account.balance<=0||
    !Array.isArray(account?.holdings))return {status:'ACCOUNT_UNAVAILABLE'};
  const pending=await sql(`SELECT ticker FROM kal_kings_directional_orders
    WHERE status IN ('SUBMITTING','UNCERTAIN','PARTIALLY_FILLED','EXIT_SUBMITTING','EXIT_UNCERTAIN') LIMIT 1`);
  if(pending.length)return {status:'HALTED_PENDING_RECONCILIATION'};
  let reason='NO_CURRENT_INDEPENDENT_EDGE',alreadyAttempted=false,attempts=0,candidateChecks=0,lastCheckedTicker=null,lastCheckedStrategy=null;
  // Sports are the primary execution queue: already-exceeded totals first,
  // then verified late-game leads, and crypto only after sports candidates.
  const priority={TOTAL_ALREADY_OVER:0,LATE_GAME_LEAD:1,CRYPTO_DIRECTIONAL_CONSENSUS:2};
  const orderedIdeas=(Array.isArray(ideas)?ideas:[]).slice().sort((a,b)=>
    (priority[a?.strategy]??99)-(priority[b?.strategy]??99)||
    (Number(b?.maxAllocationFraction)||0)-(Number(a?.maxAllocationFraction)||0));
  for(const idea of orderedIdeas){
   candidateChecks++;
   const m=idea?.market,ticker=m?.ticker;
   lastCheckedTicker=validTicker(ticker)?ticker:null;lastCheckedStrategy=String(idea?.strategy||'').slice(0,64);
   const isTotal=idea?.strategy==='TOTAL_ALREADY_OVER';
   const isCrypto=idea?.strategy==='CRYPTO_DIRECTIONAL_CONSENSUS';
   if(!['LATE_GAME_LEAD','TOTAL_ALREADY_OVER','CRYPTO_DIRECTIONAL_CONSENSUS'].includes(idea?.strategy)){reason='UNSUPPORTED_STRATEGY';continue;}
   if(idea.sourceVerified!==true){reason='INDEPENDENT_SOURCE_NOT_VERIFIED';continue;}
   if(idea.marketMatchVerified!==true||!validTicker(ticker)){reason='MARKET_MATCH_UNAVAILABLE';continue;}
   if(!isTotal&&!isCrypto&&idea.lateGameVerified!==true){reason='LATE_GAME_SIGNAL_NOT_VERIFIED';continue;}
   const ideaAge=age(idea.updatedAt,clock);
   if(!Number.isFinite(ideaAge)||ideaAge<0||ideaAge>(isCrypto?30_000:20_000)){reason='SIGNAL_STALE_OR_INVALID';continue;}
   let finalConsensus=null;
   if(isCrypto){
    const modelAge=now()-Date.parse(idea.model?.observedAt||'');
    if(!['yes','no'].includes(idea.side)||idea.model?.status!=='ESTIMATED'||
       Number(idea.model.trials)<2500||modelAge<0||modelAge>30000||
       !ticker.startsWith('KX'+idea.symbol+'15M-'))continue;
    try{finalConsensus=await fetchFinalConsensus(idea.symbol,idea)}catch{reason='CONSENSUS_UNAVAILABLE';continue;}
    const elapsed=now()-Date.parse(finalConsensus?.updatedAt||'');
    if(finalConsensus?.direction!==(idea.side==='yes'?'UP':'DOWN')||
       Number(finalConsensus.agreeingSources)<5||finalConsensus.marketTicker!==ticker||
       !Number.isFinite(elapsed)||elapsed<0||elapsed>3000){
      reason='FINAL_CONSENSUS_CHANGED';continue;
    }
   }
   const prefix=ticker.slice(0,ticker.lastIndexOf('-')+1);
   if(account.holdings.some(x=>String(x?.ticker||'').startsWith(prefix)&&
      Number.isFinite(Number(x?.position))&&Number(x.position)!==0)){
     reason='CORRELATED_EXISTING_HOLDINGS';continue;
   }
   let fresh,book=null;
   try{fresh=await fetchMarket(ticker)}
   catch{reason='FRESH_MARKET_UNAVAILABLE_OR_INACTIVE';continue;}
   if(!fresh){reason='FRESH_MARKET_UNAVAILABLE_OR_INACTIVE';continue;}
   if(fresh.id!==ticker){reason='FRESH_MARKET_TICKER_MISMATCH';continue;}
   if(!['open','active'].includes(fresh.status)){reason='FRESH_MARKET_NOT_OPEN';continue;}
   const expectedExpiry=Date.parse(fresh.expectedExpirationTime||'');
   if(Number.isFinite(expectedExpiry)&&expectedExpiry<=now()){
     reason='EXPECTED_EXPIRATION_PASSED';continue;
   }
   try{book=normalizeKalshiBook(await fetchOrderbook(ticker))}
   catch{book=null}
   const orderSide=isCrypto&&idea.side==='no'?'no':'yes';
   const resolvedBook=resolveExecutableAskBook(book,fresh,orderSide,now());
   book=resolvedBook.book;
   if(!resolvedBook.source){
     reason=resolvedBook.reason||'NO_EXECUTABLE_ASK_DEPTH';continue;
   }
   if(!Number.isFinite(Date.parse(fresh.closeTime||''))||
      Date.parse(fresh.closeTime)<=now()+10000){reason='MARKET_CLOSING';continue;}
   const best=isCrypto&&idea.side==='no'?book.noAsks[0]:book.yesAsks[0];
   if(isCrypto&&(!/CF Benchmarks/i.test(fresh.rulesPrimary||'')||
      !/simple average/i.test(fresh.rulesPrimary||'')||
      !/at least/i.test(fresh.rulesPrimary||''))){reason='SETTLEMENT_RULES_UNVERIFIED';continue;}
   // The venue supplies series-specific multipliers. Unsupported flat fees,
   // missing metadata, or an unavailable schedule are not proof of profit.
   let feeSchedule=null;
   try{feeSchedule=typeof fetchFeeSchedule==='function'?await fetchFeeSchedule(ticker):null}
   catch{feeSchedule=null}
   const feeMultiplier=Number(feeSchedule?.feeMultiplier),feeType=feeSchedule?.feeType;
   if(!feeSchedule||!['quadratic','quadratic_with_maker_fees',
       'quadratic_with_combo_maker_fees'].includes(feeType)||
       !Number.isFinite(feeMultiplier)||feeMultiplier<0||feeMultiplier>4){
     reason='FEE_SCHEDULE_UNVERIFIED';continue;
   }
   const fee=Math.max(0,Math.round(
     (estimatedKalshiBuyDebit(1,best.price,{feeMultiplier})-best.price)*10000)/10000);
   const quote={...fresh,ticker,status:fresh.status,
     yesAsk:book.yesAsks?.[0]?.price,noAsk:book.noAsks?.[0]?.price,
     yesDepth:book.yesAsks?.[0]?.quantity,noDepth:book.noAsks?.[0]?.quantity,
     observedAt:fresh.observedAt};
   const finalScore=isCrypto?cryptoConfidenceScore(idea.probability,
     Math.min(Number(idea.agreeingSources),Number(finalConsensus?.agreeingSources))):null;
   if(isCrypto&&!finalScore?.tradeEligible){reason='FINAL_CONSENSUS_CONFIDENCE_BELOW_MINIMUM';continue;}
   const decision=isTotal?assessAlreadyExceededTotal({
       game:idea.game,market:quote,bankroll:Number(account.balance),
       feePerContract:fee,feeMultiplier,holdings:account.holdings,
       holdingsComplete:account.positionsComplete,now:now()
     }):!isCrypto?planLateGameOrder({game:idea.game,market:quote,
       bankroll:Number(account.balance),feePerContract:fee,
       holdings:account.holdings,now:now()
     }):assessKalshiValue({market:quote,side:idea.side,
       probability:idea.probability,
       probabilitySource:isCrypto?'CRYPTO_SCENARIO_PROXY':'ESPN_LIVE_MODEL',sourceVerified:true,marketMatchVerified:true,
       bankroll:Number(account.balance),holdings:account.holdings,
       feePerContract:fee,now:now(),maxLossProbability:.30,
       minimumEdge:isCrypto?.02:0,
       maxBankrollFraction:isCrypto?Math.min(Number(idea.allocationFraction),Number(finalConsensus.allocationFraction)):null,
       consensusConfidenceScorePercent:finalScore?.scorePercent??null});
   if(!decision.allowed){reason=decision.reason;continue;}
   // Final account-level affordability guard: never submit a trade whose
   // all-in debit is unknown or exceeds the currently verified cash balance.
   const availableCash=Number(account.balance);
   const allInDebit=Number(decision.estimatedMaxDebitDollars);
   if(!Number.isFinite(availableCash)||availableCash<=0||
      !Number.isFinite(allInDebit)||allInDebit<=0||allInDebit>availableCash){
     reason='INSUFFICIENT_VERIFIED_BANKROLL';continue;
   }
   // Each strategy's order planner already enforces its own bankroll cap.
   // A second unrelated 2% check would falsely veto profitable total orders.
   if(attempts>=4){reason='MAX_ORDER_ATTEMPTS_THIS_CYCLE';break;}
   const clientId=createId();
   const reservationParams=[ticker,String(idea.eventKey||ticker),idea.strategy,
      decision.side,String(decision.contracts),String(decision.limitPrice),
      String(decision.estimatedFeesDollars??decision.feePerContract*decision.contracts),
      decision.modeledWinProbability==null?null:String(decision.modeledWinProbability),
      String(decision.estimatedMaxDebitDollars),clientId];
   let inserted=await sql(`INSERT INTO kal_kings_directional_orders
     (ticker,event_key,strategy,side,contracts,entry_price,estimated_fees,modeled_probability,
      max_debit,client_order_id,status,created_at,updated_at)
     VALUES($1,$2,$3,$4,$5::numeric,$6::numeric,$7::numeric,$8::numeric,
       $9::numeric,$10::uuid,'SUBMITTING',now(),now())
     ON CONFLICT(ticker) DO NOTHING RETURNING ticker`,
     reservationParams);
   if(!inserted.length){
     // A *confirmed* FOK zero-fill leaves no position. It may be retried
     // after a short cooldown on an entirely fresh book and new client ID.
     // Unknown or partial fills must never enter this recovery path.
     inserted=await sql(`UPDATE kal_kings_directional_orders
       SET status='SUBMITTING',event_key=$2,strategy=$3,side=$4,
           contracts=$5::numeric,entry_price=$6::numeric,
           estimated_fees=$7::numeric,modeled_probability=$8::numeric,
           max_debit=$9::numeric,client_order_id=$10::uuid,
           exchange_order_id=NULL,filled_count=0,updated_at=now()
       WHERE ticker=$1 AND status='NOT_FILLED'
         AND updated_at<now()-interval '15 seconds'
       RETURNING ticker`,reservationParams);
     if(!inserted.length){alreadyAttempted=true;reason='ALREADY_ATTEMPTED';continue;}
   }
   attempts++;
   const request={ticker,client_order_id:clientId,action:'buy',side:decision.side,
      count:decision.contracts,type:'limit',
      ...(decision.side==='yes'?{yes_price_dollars:decision.limitPrice.toFixed(4)}:
        {no_price_dollars:decision.limitPrice.toFixed(4)}),
      time_in_force:'fill_or_kill',self_trade_prevention_type:'taker_at_cross',
      cancel_order_on_pause:true};
   let status='UNCERTAIN',exchangeId=null,filled=0,rejectionReason=null;
   try{
     const receipt=await submit(request);
     const n=Number(receipt?.fill_count);
     exchangeId=typeof receipt?.order_id==='string'?receipt.order_id.slice(0,128):null;
     filled=Number.isFinite(n)&&n>=0?n:0;
     status=!Number.isFinite(n)?'UNCERTAIN':n===0?'NOT_FILLED':
       n>=decision.contracts?'FILLED':'PARTIALLY_FILLED';
   }catch(e){
     const code=Number(e?.httpStatus||0);
     if([400,401,403,404,422,429].includes(code)){
       status='REJECTED';
       rejectionReason=code===403||code===401?
         'KALSHI_ORDER_PERMISSION_DENIED':code===429?
         'KALSHI_RATE_LIMITED':'KALSHI_ORDER_INVALID';
     }
     // Network failures, 409 duplicates, and server timeouts remain uncertain.
   }
   await sql(`UPDATE kal_kings_directional_orders
      SET status=$2,exchange_order_id=$3,filled_count=$4::numeric,
       high_bid=$5::numeric,updated_at=now() WHERE ticker=$1`,
      [ticker,status,exchangeId,String(filled),String(decision.limitPrice)]);
   // A verified fill count of zero means no position was opened. Look for
   // another independent market immediately, without waiting a full minute.
   if(status==='NOT_FILLED'){reason='CONFIRMED_NO_FILL';continue;}
   if(status==='REJECTED')return {status,reason:rejectionReason,ticker,filled:0,candidateChecks,orderSubmissionAttempts:attempts,lastCheckedTicker,lastCheckedStrategy};
   return {status,ticker,contracts:decision.contracts,filled,
     modeledWinProbability:decision.modeledWinProbability,
     estimatedMaxDebitDollars:decision.estimatedMaxDebitDollars,
     expectedNetDollars:decision.expectedNetDollars??decision.netIfNormallySettledDollars,
     strategy:idea.strategy,candidateChecks,orderSubmissionAttempts:attempts,lastCheckedTicker,lastCheckedStrategy};
  }
  return {status:alreadyAttempted?'ALREADY_ATTEMPTED':'NO_VERIFIED_DIRECTIONAL_EDGE',reason,candidateChecks,orderSubmissionAttempts:attempts,lastCheckedTicker,lastCheckedStrategy};
 };
}

manual_execution.mjs:
/** One explicit dashboard action is required per real-money manual order.
 * Previews never submit. Intents are claimed atomically before Kalshi POST.
 */
import {planManualKalshiBuy,buildManualBuyOrder} from './manual_trading.mjs';
import {estimatedKalshiBuyDebit} from './engine.mjs';
const tickerOk=t=>typeof t==='string'&&/^[A-Z0-9_-]{4,128}$/.test(t);
const uuidOk=id=>typeof id==='string'&&/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(id);
export function classifyKalshiManualError(err){
 const code=Number(err?.httpStatus||0);
 if([400,401,403,404,422,429].includes(code)){
  const reason=code===401||code===403?'KALSHI_ORDER_PERMISSION_DENIED':
   code===429?'KALSHI_RATE_LIMITED':'KALSHI_ORDER_INVALID';
  return {status:'REJECTED',reason,exchangeStatus:code};
 }
 return {status:'UNCERTAIN',reason:'ORDER_RECEIPT_UNCONFIRMED',
   exchangeStatus:Number.isInteger(code)&&code>0?code:null};
}
export function makeManualExecutor({sql,fetchAccount,fetchMarket,fetchOrderbook,
 fetchFeeSchedule,fetchOrders=async()=>[],cancelOrder=async()=>null,submit,createId,now=Date.now}){
 async function livePlan({ticker,side,count}){
   const [account,market,book,fees]=await Promise.all([
     fetchAccount(),fetchMarket(ticker),fetchOrderbook(ticker),fetchFeeSchedule(ticker)
   ]);
   if(account?.status!=='VERIFIED'||account?.positionsComplete!==true||
      !Array.isArray(account?.holdings))return {allowed:false,reason:'ACCOUNT_UNAVAILABLE'};
   return planManualKalshiBuy({market,bookResponse:book,feeSchedule:fees,
      side,count,bankroll:Number(account.balance),now:now()});
 }
 async function preview({ticker,side,count}={}){
   if(!tickerOk(ticker)||!['yes','no'].includes(side)||!Number.isInteger(count)||
      count<1||count>50)return {allowed:false,reason:'INVALID_ORDER_REQUEST'};
   let plan;
   try{plan=await livePlan({ticker,side,count})}
   catch{return {allowed:false,reason:'LIVE_QUOTE_UNAVAILABLE'}}
   if(!plan?.allowed)return plan;
   // The user explicitly confirms the maximum price shown in preview,
   // allowing a one-cent cushion for ordinary live book movement.
   const currentBestAsk=plan.limitPrice;
   const limit=Math.min(.9999,Math.round((currentBestAsk+.01)*10000)/10000);
   if(limit>currentBestAsk){
     const total=estimatedKalshiBuyDebit(count,limit,{feeMultiplier:plan.feeMultiplier});
     if(total<=Number(plan.maximumRiskBudgetDollars)+1e-8){
       plan={...plan,limitPrice:limit,maxDebitDollars:total,
         estimatedFeeDollars:Math.round((total-count*limit)*10000)/10000,
         conditionalProfitIfWinDollars:Math.round((count-total)*10000)/10000,
         maximumLossIfLoseDollars:total};
     }
   }
   plan={...plan,currentBestAsk};
   const id=createId(),orderId=createId();
   if(!uuidOk(id)||!uuidOk(orderId)||id===orderId)return {allowed:false,reason:'ORDER_ID_UNAVAILABLE'};
   const expiresAt=new Date(now()+30000).toISOString();
   await sql(`INSERT INTO kal_kings_manual_intents
      (id,ticker,side,contracts,limit_price,max_debit,client_order_id,status,expires_at)
      VALUES($1::uuid,$2,$3,$4::integer,$5::numeric,$6::numeric,$7::uuid,
       'PREVIEW',now()+interval '30 seconds')
      RETURNING id`,
      [id,ticker,side,String(count),String(plan.limitPrice),
       String(plan.maxDebitDollars),orderId]);
   return {...plan,intentId:id,expiresAt,
     note:'No order has been sent. Confirm to buy this speculative contract.'};
 }
 async function execute({intentId}={}){
   if(!uuidOk(intentId))return {status:'INVALID_INTENT'};
   // One and only one caller can claim a previewed intent. Stale, already
   // accepted, or partially filled orders cannot accidentally be resubmitted.
   const claimed=await sql(`UPDATE kal_kings_manual_intents
     SET status='SUBMITTING',updated_at=now()
     WHERE id=$1::uuid AND status='PREVIEW' AND expires_at>now()
     RETURNING id,ticker,side,contracts::integer AS count,
       limit_price::text AS limit_price,max_debit::text AS max_debit,
       client_order_id`,[intentId]);
   const row=claimed?.[0];
   if(!row)return {status:'ALREADY_ATTEMPTED'};
   let plan;
   try{plan=await livePlan({ticker:row.ticker,side:row.side,count:Number(row.count)})}
   catch{plan={allowed:false,reason:'LIVE_REQUOTE_UNAVAILABLE'}}
   if(!plan?.allowed||plan.ticker!==row.ticker||plan.side!==row.side||
      plan.count!==Number(row.count)||
      plan.limitPrice>Number(row.limit_price)+1e-8||
      plan.maxDebitDollars>Number(row.max_debit)+1e-8){
     const reason=plan?.allowed?'QUOTE_MOVED_OR_COST_INCREASED':plan?.reason||'RECHECK_FAILED';
     await sql(`UPDATE kal_kings_manual_intents SET status=$2,
       updated_at=now() WHERE id=$1::uuid`,[intentId,'NOT_ELIGIBLE']);
     return {status:'NOT_ELIGIBLE',reason};
   }
   let status='UNCERTAIN',exchangeOrderId=null,filled=0,failureReason=null;
   try{
     const order=buildManualBuyOrder(plan,row.client_order_id);
     const response=await submit(order);
     exchangeOrderId=typeof response?.order_id==='string'?response.order_id.slice(0,128):null;
     const n=Number(response?.fill_count);
     if(Number.isFinite(n)&&n>=0&&n<=plan.count){
       filled=n;
       status=n===0?'NOT_FILLED':n>=plan.count?'FILLED':'PARTIALLY_FILLED';
     }
   }catch(e){
     const classification=classifyKalshiManualError(e);
     status=classification.status;
     failureReason=classification.reason;
     // Provider 4xx (except ambiguous 409) explicitly rejected the request.
     // Network errors and server failures may have occurred after a fill.
   }
   await sql(`UPDATE kal_kings_manual_intents
       SET status=$2,exchange_order_id=$3,filled_count=$4::numeric,
       last_error=$5,updated_at=now() WHERE id=$1::uuid`,
       [intentId,status,exchangeOrderId,String(filled),failureReason]);
   return {status,reason:failureReason,ticker:plan.ticker,side:plan.side,count:plan.count,
     filled,limitPrice:plan.limitPrice,maxDebitDollars:plan.maxDebitDollars,
     orderId:exchangeOrderId,
     note:status==='UNCERTAIN'?'Exchange receipt was inconclusive; do not retry before reconciling Kalshi.':
       'Only exchange-confirmed fills represent purchased contracts.'};
 }
 async function reconcilePending({readOrderHistory=fetchOrders,cancelUnfilledOrder=cancelOrder}={}){
   if(typeof readOrderHistory!=='function')return {checked:0,confirmed:0};
   const pending=await sql(`SELECT id,ticker,contracts,client_order_id,status
      FROM kal_kings_manual_intents
      WHERE status IN ('UNCERTAIN','SUBMITTING')
      AND updated_at<now()-interval '3 seconds'
      ORDER BY updated_at ASC LIMIT 12`);
   let confirmed=0,checked=0;
   for(const row of pending){
     let orders=[];
     try{orders=await readOrderHistory(row.ticker)}
     catch{continue}
     checked++;
     const match=(Array.isArray(orders)?orders:[]).find(x=>
       x.ticker===row.ticker&&x.client_order_id===row.client_order_id);
     if(!match||typeof match.order_id!=='string')continue;
     const n=Number(match.fill_count_fp??match.fill_count);
     if(!Number.isFinite(n)||n<0||n>Number(row.contracts))continue;
     // A RESTING unfilled order must be canceled at Kalshi before local cleanup.
     // Cancellation and its confirmation are separate requests to handle fills
     // that race with cancellation; unknown orders must remain uncertain.
     let verified=match,verifiedCount=n;
     if(match.status==='resting'||match.status==='pending'){
       if(typeof cancelUnfilledOrder!=='function')continue;
       try {
         const canceled=await cancelUnfilledOrder(match.order_id,row.ticker);
         if(canceled?.order_id!==match.order_id)continue;
         const latest=await readOrderHistory(row.ticker);
         const found=(Array.isArray(latest)?latest:[]).find(x=>
           x.ticker===row.ticker&&x.client_order_id===row.client_order_id&&
           x.order_id===match.order_id);
         if(!found||!['canceled','executed'].includes(found.status))continue;
         verified=found;
         verifiedCount=Number(found.fill_count_fp??found.fill_count);
         if(!Number.isFinite(verifiedCount)||verifiedCount<0||
           verifiedCount>Number(row.contracts))continue;
       }catch{continue}
     }
     let next;
     if(verifiedCount>=Number(row.contracts))next='FILLED';
     else if(verifiedCount>0&&['canceled','executed'].includes(verified.status))next='PARTIALLY_FILLED';
     else if(verifiedCount===0&&['canceled','executed'].includes(verified.status))next='NOT_FILLED';
     else continue;
     await sql(`UPDATE kal_kings_manual_intents
       SET status=$2,exchange_order_id=$3,filled_count=$4::numeric,
       last_error=NULL,updated_at=now()
       WHERE id=$1::uuid AND status IN ('UNCERTAIN','SUBMITTING')`,
       [row.id,next,verified.order_id,String(verifiedCount)]);
     confirmed++;
   }
   return {checked,confirmed};
 }
 return {preview,execute,reconcilePending};
}

manual_trading.mjs:
/**
 * Exchange-verified manual Kalshi trade ticket.
 *
 * Manual means the user explicitly chooses a speculative YES/NO purchase.
 * The trade preview never represents recent crypto momentum as profit.
 */
import {estimatedKalshiBuyDebit} from './engine.mjs';
import {normalizeKalshiBook,sweepAsks} from './quant.mjs';
const ok=n=>typeof n==='number'&&Number.isFinite(n);
const round4=n=>Math.round(n*10000)/10000;
const denied=reason=>({allowed:false,reason});
export function planManualKalshiBuy({market,bookResponse,feeSchedule,side,count,bankroll,
  now=Date.now(),maxBankrollFraction=.25}={}){
 if(!['yes','no'].includes(side)||!Number.isInteger(count)||count<1||count>50)
   return denied('INVALID_TICKET');
 if(!/^[A-Z0-9_-]{4,128}$/.test(market?.id||'')||
   !['open','active'].includes(market?.status))
   return denied('NO_OPEN_MATCHING_CONTRACT');
 const age=now-Date.parse(market?.observedAt||''),timeLeft=Date.parse(market?.closeTime||'')-now;
 if(!ok(age)||age<0||age>3000||!ok(timeLeft)||timeLeft<5000)
   return denied('STALE_OR_CLOSING_CONTRACT');
 const cash=Number(bankroll);
 if(!ok(cash)||cash<=0||!ok(maxBankrollFraction)||maxBankrollFraction<=0||
    maxBankrollFraction>.25)return denied('INSUFFICIENT_BANKROLL');
 const feeType=feeSchedule?.feeType,feeMultiplier=Number(feeSchedule?.feeMultiplier);
 if(!feeSchedule||!['quadratic','quadratic_with_maker_fees',
       'quadratic_with_combo_maker_fees'].includes(feeType)||
       !ok(feeMultiplier)||feeMultiplier<0||feeMultiplier>4)
   return denied('FEE_SCHEDULE_NOT_VERIFIED');
 let book;
 try{book=normalizeKalshiBook(bookResponse)}catch{return denied('ORDERBOOK_UNAVAILABLE')}
 const available=side==='yes'?book.yesAsks:book.noAsks;
 const sweep=sweepAsks(available,count);
 if(!sweep||!ok(sweep.worstPrice)||sweep.worstPrice<=0||sweep.worstPrice>=1)
   return denied('INSUFFICIENT_LIQUIDITY');
 const price=sweep.worstPrice,fullDebit=estimatedKalshiBuyDebit(count,price,{feeMultiplier});
 if(fullDebit>cash+1e-8||fullDebit>maxBankrollFraction*cash+1e-8)
   return denied('INSUFFICIENT_RISK_BUDGET');
 const fee=Math.max(0,fullDebit-price*count);
 return {allowed:true,reason:'MANUAL_LIMIT_ORDER_PREVIEW',ticker:market.id,side,count,
    limitPrice:price,feeMultiplier,feeType,estimatedFeeDollars:round4(fee),
    maxDebitDollars:fullDebit,maximumRiskBudgetDollars:Math.round(maxBankrollFraction*cash*10000)/10000,
    conditionalProfitIfWinDollars:round4(count-fullDebit),
    maximumLossIfLoseDollars:fullDebit,quoteObservedAt:market.observedAt,
    marketCloseTime:market.closeTime,priceBasis:'LIVE_EXCHANGE_ORDERBOOK',
    note:'A YES or NO signal is not a verified future outcome. Purchase is speculative and may lose the full debit.'};
}
export function buildManualBuyOrder(plan,clientOrderId){
 if(!plan?.allowed||!['yes','no'].includes(plan.side)||
   !Number.isInteger(plan.count)||plan.count<1||
   !/^[A-Z0-9_-]{4,128}$/.test(plan.ticker||'')||
   !/^[a-f0-9]{8}-[a-f0-9-]{27}$/i.test(clientOrderId||''))
   throw RangeError('Invalid manual trade intent');
 const yesScale=plan.side==='yes'?plan.limitPrice:1-plan.limitPrice;
 if(!ok(yesScale)||yesScale<=0||yesScale>=1)throw RangeError('Invalid order price');
 return {ticker:plan.ticker,client_order_id:clientOrderId,
   action:'buy',side:plan.side,count:plan.count,
   ...(plan.side==='yes'?{yes_price_dollars:plan.limitPrice.toFixed(4)}:
     {no_price_dollars:plan.limitPrice.toFixed(4)}),
   type:'limit',time_in_force:'fill_or_kill',
   self_trade_prevention_type:'taker_at_cross',cancel_order_on_pause:true};
}

market_universe.mjs:
/** Rotating, category-inclusive Kalshi market discovery.
 * Discovery is not an independent win forecast and never places an order.
 */
const numeric=x=>x===null||x===undefined||x===''?NaN:Number(x);
const positive=x=>Number.isFinite(x)&&x>0&&x<1;
const clean=(x,max=180)=>String(x||'').trim().slice(0,max);
const groups=[
  ['SPORTS',/^(KXNFL|KXNBA|KXNHL|KXMLB|KXCFB|KXCBB|KXEPL|KXMLS|KXSPORT|KXUFC|KXTENNIS|KXNCAA|KXWNBA)/],
  ['CRYPTO',/^(KXBTC|KXETH|KXSOL|KXXRP|KXDOGE|KXADA|KXBNB|KXLINK|KXDOT|KXZEC|KXLTC|KXCRYPTO|BTCMAX)/],
  ['WEATHER',/^(KXHIGH|KXLOW|KXRAIN|KXSNOW|KXTEMP|KXHURRICANE|KXWIND|KXHEAT)/],
  ['ECONOMICS',/^(KXCPI|KXPCE|KXGDP|KXFED|KXUNEMP|KXJOBS|KXNFP|KXINFLATION|KXRECESSION)/],
  ['ELECTIONS',/^(KXPRES|KXHOUSE|KXSENATE|KXGOV|KXPRIMARY|KXELECTION|KXCONGRESS)/],
  ['FINANCIALS',/^(KXSPX|KXSP500|KXNASDAQ|KXDJIA|KXRATE|KXSTOCK)/],
  ['SCIENCE_TECH',/^(KXAI|KXTECH|KXSPACE|KXLAUNCH|KXROCKET)/]
];
export function classifyKalshiMarket(row){
 const symbol=String(row?.series||row?.ticker||'').split('-')[0].toUpperCase();
 return groups.find(([_,re])=>re.test(symbol))?.[0]||'OTHER';
}
export function normalizeKalshiMarket(m,now=Date.now()){
 if(!m||typeof m.ticker!=='string'||!/^[A-Z0-9_-]{4,128}$/.test(m.ticker)||
   !['open','active'].includes(m.status)||m.market_type&&m.market_type!=='binary')return null;
 const expiration=Date.parse(m.close_time||'');
 if(!Number.isFinite(expiration)||expiration<=now)return null;
 const yes=numeric(m.yes_ask_dollars??(m.yes_ask!=null?Number(m.yes_ask)/100:null));
 const no=numeric(m.no_ask_dollars??(m.no_ask!=null?Number(m.no_ask)/100:null));
 if(!positive(yes)&&!positive(no))return null;
 const bid=numeric(m.yes_bid_dollars??(m.yes_bid!=null?Number(m.yes_bid)/100:null));
 const noBid=numeric(m.no_bid_dollars??(m.no_bid!=null?Number(m.no_bid)/100:null));
 const depth=numeric(m.yes_ask_size_fp??m.yes_ask_size);
 const noDepth=numeric(m.no_ask_size_fp??m.no_ask_size);
 const volume=numeric(m.volume_24h_fp??m.volume_24h??m.volume_fp??m.volume);
 const ticker=m.ticker,series=ticker.split('-')[0];
 const result={ticker,series,eventTicker:clean(m.event_ticker,145),
   title:clean(m.title||m.yes_sub_title||ticker),status:m.status,yesAsk:positive(yes)?yes:null,
   noAsk:positive(no)?no:null,yesBid:positive(bid)?bid:null,noBid:positive(noBid)?noBid:null,
   yesDepth:Number.isFinite(depth)&&depth>=0?depth:null,
   noDepth:Number.isFinite(noDepth)&&noDepth>=0?noDepth:null,
   volume24h:Number.isFinite(volume)&&volume>=0?volume:0,
   closeTime:m.close_time,observedAt:new Date(now).toISOString(),category:null,
   verifiedExpectedProfit:null,eligibleForAutomation:false,reviewOnly:true,
   note:'Tradable quote only. No independent model of fair value or verified net profit.'};
 result.category=classifyKalshiMarket(result);
 return result;
}
export function rankUniverseIdeas(rows,{max=24}={}){
 const eligible=(Array.isArray(rows)?rows:[]).filter(r=>r?.ticker&&
   (positive(r.yesAsk)||positive(r.noAsk)));
 const scored=eligible.map(x=>{
   const yesSpread=x.yesAsk!=null&&x.yesBid!=null?x.yesAsk-x.yesBid:1;
   const noSpread=x.noAsk!=null&&x.noBid!=null?x.noAsk-x.noBid:1;
   const spread=Math.min(yesSpread,noSpread);
   const liq=Math.min(100000,Number(x.volume24h||0));
   return {...x,discoveryScore:Math.round(1000*Math.log1p(liq)/(1+Math.max(0,spread)*50))/1000,
     estimatedPriceSpread:Math.round(spread*10000)/10000};
 }).sort((a,b)=>b.discoveryScore-a.discoveryScore);
 const output=[],used=new Set();
 // Cover different kinds of instruments before filling by liquidity.
 for(const x of scored)if(!used.has(x.category)){output.push(x);used.add(x.category);if(output.length>=max)return output;}
 for(const x of scored){if(output.some(y=>y.ticker===x.ticker))continue;output.push(x);if(output.length>=max)break;}
 return output;
}
export async function scanUniversePage({fetcher,cursor='',now=Date.now(),limit=500}={}){
 if(typeof fetcher!=='function')throw Error('Missing public market data adapter');
 const pageSize=Math.min(1000,Math.max(10,Math.floor(Number(limit)||500)));
 const params=new URLSearchParams({status:'open',mve_filter:'exclude',limit:String(pageSize)});
 if(cursor)params.set('cursor',String(cursor));
 const path='/markets?'+params.toString();
 const data=await fetcher(path);
 if(!Array.isArray(data?.markets))throw Error('Kalshi public market list malformed');
 const rows=data.markets.map(m=>normalizeKalshiMarket(m,now)).filter(Boolean);
 const byCategory={};
 for(const r of rows)byCategory[r.category]=(byCategory[r.category]||0)+1;
 return {scanned:data.markets.length,eligibleQuoted:rows.length,byCategory,
   nextCursor:typeof data.cursor==='string'&&data.cursor?data.cursor:null,
   research:rankUniverseIdeas(rows),marketSample:rows,
   completedSweep:!data.cursor,asOf:new Date(now).toISOString(),
   note:'Rolling page of a larger Kalshi market universe. Research prices do not establish profitable trades.'};
}

predictive_feeds.mjs:
/** Kal Kings independent live signal-feed adapters. Read-only; never place orders. */
import {cryptoConsensus,assessLateGame,assessTotals} from './predictive_strategies.mjs';
import {technicalIndicators,assessCryptoRegime,matchSportsOutcome,assessTotalsProjection} from './strategy_optimizer.mjs';
import {additionalSpotCandles} from './spot_venue_adapters.mjs';
import {runCryptoMonteCarlo} from './crypto_trade_model.mjs';
const KALSHI='https://api.elections.kalshi.com/trade-api/v2';
const ESPN='https://site.api.espn.com/apis/site/v2/sports';
const integer=n=>Number.isFinite(Number(n))?Number(n):null;
const timeout=()=>typeof AbortSignal==='undefined'?undefined:AbortSignal.timeout(7000);
async function json(fetcher,url){
 const r=await fetcher(url,{method:'GET',signal:timeout(),redirect:'error'});
 if(!r?.ok)throw Error('HTTP_'+Number(r?.status||0));
 return r.json();
}
const candidates={
 ETH:{coinbase:'ETH-USD',kraken:'ETHUSD',bitstamp:'ethusd'},
 SOL:{coinbase:'SOL-USD',kraken:'SOLUSD',bitstamp:'solusd'},
 XRP:{coinbase:'XRP-USD',kraken:'XRPUSD',bitstamp:'xrpusd'},
 DOGE:{coinbase:'DOGE-USD',kraken:'DOGEUSD',bitstamp:'dogeusd'},
 ADA:{coinbase:'ADA-USD',kraken:'ADAUSD',bitstamp:'adausd'}
};
function momentum(rows,{symbol,source,now}){
 const sorted=(Array.isArray(rows)?rows:[]).map(r=>({time:integer(r.time),lastSampleTime:integer(r.lastSampleTime),
  open:integer(r.open),close:integer(r.close),high:integer(r.high),low:integer(r.low),volume:integer(r.volume)}))
  .filter(r=>r.time!==null&&r.open>0&&r.close>0&&r.time<=Math.floor(now/1000)+120)
  .sort((a,b)=>a.time-b.time);
 const latest=sorted.at(-1),first=sorted.at(-4);
 if(!latest||!first||now-(latest.lastSampleTime??latest.time)*1000>360000||
   latest.time-first.time<600||latest.time-first.time>1500)return null;
 return {symbol,source,start:first.open,last:latest.close,candles:sorted.slice(-35),
   indicators:technicalIndicators(sorted),observedAt:new Date(now).toISOString(),
   oldestCandleAt:new Date(first.time*1000).toISOString(),newestCandleAt:new Date(latest.time*1000).toISOString()};
}
export async function spotMomentum(fetcher,symbol,now){
 const pair=candidates[symbol];if(!pair)return [];
 const names=['coinbase','kraken','bitstamp','gemini','okx','kucoin','bitfinex'];
 const providers=names.map(async source=>{
  let j,rows;
  if(source==='coinbase'){
   j=await json(fetcher,`https://api.exchange.coinbase.com/products/${pair.coinbase}/candles?granularity=300`);
   rows=Array.isArray(j)?j.map(x=>({time:x[0],open:x[3],high:x[2],low:x[1],close:x[4],volume:x[5]})):[];
  }else if(source==='kraken'){
   j=await json(fetcher,`https://api.kraken.com/0/public/OHLC?pair=${pair.kraken}&interval=5`);
   if(j.error?.length)throw Error('Kraken data error');
   const array=Object.values(j.result||{}).find(Array.isArray)||[];
   rows=array.map(x=>({time:x[0],open:x[1],high:x[2],low:x[3],close:x[4],volume:x[6]}));
  }else if(source==='bitstamp'){
   j=await json(fetcher,`https://www.bitstamp.net/api/v2/ohlc/${pair.bitstamp}/?step=300&limit=75`);
   rows=(j.data?.ohlc||[]).map(x=>({time:x.timestamp,open:x.open,high:x.high,low:x.low,close:x.close,volume:x.volume}));
  }else{
   rows=await additionalSpotCandles(fetcher,symbol,source);
  }
  return momentum(rows,{symbol,source,now});
 });
 const settled=await Promise.allSettled(providers);
 const valid=settled.filter(x=>x.status==='fulfilled'&&x.value).map(x=>x.value);
 valid.missingSources=settled.flatMap((x,i)=>{
  if(x.status==='fulfilled'&&x.value)return [];
  const message=x.status==='rejected'?String(x.reason?.message||''):'';
  return [{source:names[i],reason:/^HTTP_\d+$/.test(message)?message:
   /timeout|abort/i.test(message)?'TIMEOUT':
   x.status==='fulfilled'?'INVALID_OR_STALE_CANDLES':'PROVIDER_FAILURE'}];
 });
 return valid;
}

const SPORTS_MARKET_SERIES={NFL:'KXNFLGAME',NBA:'KXNBAGAME',NHL:'KXNHLGAME',MLB:'KXMLBGAME',CFB:'KXCFBGAME',CBB:['KXCBBGAME','KXNCAAMBGAME'],EPL:'KXEPLGAME',MLS:'KXMLSGAME',WNBA:'KXWNBAGAME'};
const SPORTS_TOTAL_SERIES={NFL:'KXNFLTOTAL',NBA:'KXNBATOTAL',NHL:'KXNHLTOTAL',MLB:'KXMLBTOTAL',CFB:'KXCFBTOTAL',CBB:['KXCBBTOTAL','KXNCAAMBTOTAL'],EPL:'KXEPLTOTAL',MLS:'KXMLSTOTAL',WNBA:'KXWNBATOTAL'};
function matchesSportsTicker(sport,series,dateCode,away,home,ticker){
 const t=String(ticker||'');
 if(sport==='MLB')return new RegExp('^'+series+'-'+dateCode+'\\d{4}(?:'+away+home+'|'+home+away+')-').test(t);
 return t.startsWith(series+'-'+dateCode+away+home+'-')||
   t.startsWith(series+'-'+dateCode+home+away+'-');
}
const safe=val=>{if(val===null||val===undefined||val==='')return null;const n=Number(val);return Number.isFinite(n)?n:null;};
// Kalshi's legacy quote fields are integer cents; *_dollars fields are dollars.
const kalshiPrice=(dollars,cents)=>{
 if(dollars!==null&&dollars!==undefined&&dollars!==''){
  const n=Number(dollars);return Number.isFinite(n)&&n>=0&&n<=1?n:null;
 }
 if(cents!==null&&cents!==undefined&&cents!==''){
  const n=Number(cents);return Number.isFinite(n)&&n>=0&&n<=100?n/100:null;
 }
 return null;
};
const kalshiDepth=(fp,legacy)=>{
 const v=fp!==null&&fp!==undefined&&fp!==''?fp:legacy;
 if(v===null||v===undefined||v==='')return null;
 const n=Number(v);return Number.isFinite(n)&&n>=0?n:null;
};
function parseClockSeconds(value,sport,period){
 if(typeof value==='number'&&Number.isFinite(value))return value;
 const raw=String(value??'').trim();
 const match=raw.match(/^(\d+):(\d{2})(?:\.\d+)?$/);
 if(match){
   const seconds=Number(match[1])*60+Number(match[2]);
   return ['EPL','MLS'].includes(sport)&&Number(period)===2?Math.max(0,5400-seconds):seconds;
 }
 const n=Number(raw);
 return Number.isFinite(n)?n:NaN;
}
function easternDate(when){
 const d=new Date(when);
 if(!Number.isFinite(d.valueOf()))return null;
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',
   year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);
 const get=x=>parts.find(p=>p.type===x)?.value;
 return get('year')+'-'+get('month')+'-'+get('day');
}
export function parseLiveWinProbability(summary,event,now=Date.now()){
 const unavailable={homeProbability:null,awayProbability:null,sourceVerified:false,reason:'ESPN_PLAY_NOT_VERIFIED'};
 const item=Array.isArray(summary?.winprobability)?summary.winprobability.at(-1):null;
 const home=safe(item?.homeWinPercentage),tie=safe(item?.tiePercentage??0);
 const competition=event?.competitions?.[0];
 const lastScorePlay=String(competition?.situation?.lastPlay?.id||'');
 const modelPlay=String(item?.playId||'');
 const summaryState=summary?.header?.competitions?.[0]?.status?.type?.state;
 if(!event?.id||String(summary?.header?.id)!==String(event.id)||
   !modelPlay||(lastScorePlay&&lastScorePlay!==modelPlay)||
   (summaryState&&summaryState!=='in')||
   (event.status?.type?.state&&event.status.type.state!=='in')||
   home===null||home<0||home>1||tie===null||tie<0||tie>1||
   home+tie>1.001)return unavailable;
 if(!lastScorePlay){
   // Scoreboard situation.lastPlay is frequently omitted by ESPN.
   // Only substitute a summary play if its game, period, BOTH scores and
   // recorded wallclock match the fresh live scoreboard.
   const plays=[...(summary?.drives?.current?.plays||[]),
     ...(summary?.drives?.previous?.at(-1)?.plays||[]),
     ...(summary?.plays||[])];
   const play=plays.find(x=>String(x?.id||'')===modelPlay);
   const homeTeam=competition?.competitors?.find(x=>x.homeAway==='home');
   const awayTeam=competition?.competitors?.find(x=>x.homeAway==='away');
   const scoreboardPeriod=Number(event?.status?.period??competition?.status?.period);
   const lastPeriod=Number(play?.period?.number);
   const observed=now-Date.parse(play?.wallclock||'');
   const scoreClock=event?.status?.clock??competition?.status?.clock;
   const playClockMatch=/^(\d{1,2}):(\d{2})$/.exec(String(play?.clock?.displayValue||''));
   const lastClock=playClockMatch?60*Number(playClockMatch[1])+Number(playClockMatch[2]):null;
   // Scores can be unchanged for several minutes while the model becomes stale.
   // Require play clock agreement when both clocks are supplied.
   if(scoreClock!=null&&lastClock!=null&&Number.isFinite(Number(scoreClock))&&
      Math.abs(Number(scoreClock)-lastClock)>30)return unavailable;
   if(!play||!Number.isFinite(observed)||observed<0||observed>90000||
     !Number.isFinite(scoreboardPeriod)||!Number.isFinite(lastPeriod)||
     scoreboardPeriod!==lastPeriod||
     !homeTeam||!awayTeam||Number(homeTeam.score)!==Number(play.homeScore)||
     Number(awayTeam.score)!==Number(play.awayScore))
       return unavailable;
 }
 return {homeProbability:home,awayProbability:Math.max(0,1-home-tie),
   sourceVerified:true,source:'ESPN_LIVE_MODEL',modelPlayId:modelPlay,
   reason:lastScorePlay?'MATCHED_SCOREBOARD_PLAY':'MATCHED_FRESH_SUMMARY_PLAY'};
}
export function selectSportsMarket(event,markets){
 for(const market of Array.isArray(markets)?markets:[]){
   if(!['open','active'].includes(market.status))continue;
   if(matchSportsOutcome(event,market).matched)return market;
 }
 return null;
}
export function selectTotalsMarket(game,markets){
 const prefix=SPORTS_TOTAL_SERIES[game?.sport],date=game?.date;
 if(!prefix||typeof date!=='string'||!Number.isFinite(Date.parse(date+'T12:00:00Z')))return null;
 const [y,m,d]=date.split('-'),code=d+['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][Number(m)-1]+y.slice(-2);
 const a=String(game?.awayAbbreviation||'').toUpperCase(),h=String(game?.homeAbbreviation||'').toUpperCase();
 if(!a||!h||a===h||!Number.isFinite(Number(game?.totalLine)))return null;
 const prefixes=Array.isArray(prefix)?prefix:[prefix];
 const matches=(Array.isArray(markets)?markets:[]).filter(q=>
  prefixes.some(series=>matchesSportsTicker(game.sport,series,code,a,h,q.ticker))&&
  ['active','open'].includes(q.status)&&q.floorStrike!=null&&
  Number.isFinite(Number(q.floorStrike))&&q.yesAsk>0&&q.yesAsk<1&&
  /(collectively score more than|score more goals than|score more runs than|combined score.*more than)/i.test(q.rulesPrimary||''))
  .map(q=>({q,delta:Math.abs(Number(q.floorStrike)+.5-Number(game.totalLine))}))
  .sort((x,y)=>x.delta-y.delta);
 return matches[0]&&matches[0].delta<=3?matches[0].q:null;
}

/** Examine every executable score-crossed total, not only the line shown
 * by an unrelated sportsbook. Each is reverified against the actual
 * exchange order book before any order can be submitted.
 */
export function selectExceededTotalsMarkets(game,markets,{now=Date.now(),max=24}={}){
 const series=SPORTS_TOTAL_SERIES[game?.sport];
 const date=game?.date,score=Number(game?.homeScore)+Number(game?.awayScore);
 if(!series||typeof date!=='string'||!Number.isFinite(Date.parse(date+'T12:00:00Z'))||
    !Number.isFinite(score)||score<=0)return [];
 const [year,month,day]=date.split('-');
 const short=day+['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][Number(month)-1]+year.slice(-2);
 const home=String(game?.homeAbbreviation||'').toUpperCase(),
   away=String(game?.awayAbbreviation||'').toUpperCase();
 if(!/^[A-Z]{2,4}$/.test(home)||!/^[A-Z]{2,4}$/.test(away)||home===away)return [];
 return (Array.isArray(markets)?markets:[]).filter(x=>{
   const strike=Number(x?.floorStrike),ask=Number(x?.yesAsk),depth=Number(x?.yesDepth);
   return (Array.isArray(series)?series:[series]).some(type=>matchesSportsTicker(game.sport,type,short,away,home,x.ticker))&&
     ['active','open'].includes(x.status)&&
     Number.isFinite(strike)&&strike>0&&score>strike&&
     Number.isFinite(ask)&&ask>0&&ask<1&&
     Number.isFinite(depth)&&depth>=1&&
     Date.parse(x.closeTime||'')>now+10000&&
     /(collectively score more than|score more goals than|score more runs than|combined score.*more than)/i.test(String(x.rulesPrimary||''))&&
     String(x.rulesPrimary||'').includes(String(strike))&&
     /resolves? to Yes/i.test(String(x.rulesPrimary||''));
 }).sort((a,b)=>
   (a.yesAsk-b.yesAsk)||(Date.parse(a.closeTime)-Date.parse(b.closeTime)))
 .slice(0,max);
}

async function fetchSportsMarkets(fetcher,sport,now,kind='game'){
 const configured=(kind==='total'?SPORTS_TOTAL_SERIES:SPORTS_MARKET_SERIES)[sport];
 const seriesList=(Array.isArray(configured)?configured:[configured]).filter(Boolean);
 if(!seriesList.length)return [];
 const normalize=markets=>(Array.isArray(markets)?markets:[]).map(m=>({
   ticker:m.ticker,status:m.status,eventTicker:m.event_ticker,
   yesAsk:kalshiPrice(m.yes_ask_dollars,m.yes_ask),noAsk:kalshiPrice(m.no_ask_dollars,m.no_ask),
   yesBid:kalshiPrice(m.yes_bid_dollars,m.yes_bid),noBid:kalshiPrice(m.no_bid_dollars,m.no_bid),
   yesDepth:kalshiDepth(m.yes_ask_size_fp,m.yes_ask_size),
   noDepth:kalshiDepth(m.no_ask_size_fp,m.no_ask_size),
   rulesPrimary:m.rules_primary||'',floorStrike:safe(m.floor_strike),closeTime:m.close_time,
   observedAt:new Date(now).toISOString(),eventTitle:m.event_ticker||'',
   marketTitle:m.title||m.subtitle||'',source:'Kalshi'
 }));
 const batches=await Promise.allSettled(seriesList.map(async series=>{
   let all=[],cursor=null;
   for(let page=0;page<5;page++){
     let url=KALSHI+'/markets?series_ticker='+encodeURIComponent(series)+'&status=open&limit=1000';
     if(cursor)url+='&cursor='+encodeURIComponent(cursor);
     const j=await json(fetcher,url);
     all.push(...(j.markets||[]));cursor=j.cursor||null;
     if(!cursor)break;
   }
   if(!all.length){
     try{
       const events=await json(fetcher,KALSHI+'/events?series_ticker='+
         encodeURIComponent(series)+'&status=open&limit=200&with_nested_markets=true');
       all=(events.events||[]).flatMap(e=>Array.isArray(e.markets)?e.markets:[]);
     }catch{/* No fallback data means no verified candidate. */}
   }
   return normalize(all);
 }));
 const unique=new Map();
 for(const batch of batches)if(batch.status==='fulfilled')
   for(const market of batch.value)if(market.ticker&&!unique.has(market.ticker))
     unique.set(market.ticker,market);
 return [...unique.values()];
}
export function calculateCryptoWindowReference(spot,closeTime){
 const target=Date.parse(closeTime||'')-900000,opens=[],current=[];
 for(const item of spot||[]){
  const bar=item.candles?.find(c=>Math.abs(Number(c.time)*1000-target)<30000);
  if(Number(bar?.open)>0&&Number(item.last)>0){
   opens.push(Number(bar.open));current.push(Number(item.last));
  }
 }
 if(opens.length<5||Math.max(...opens)/Math.min(...opens)>1.02)return null;
 const median=x=>x.sort((a,b)=>a-b)[Math.floor(x.length/2)];
 return {referencePrice:median(opens),spotPrice:median(current),
  sourceCount:opens.length,source:'SPOT_OPEN_PROXY_NOT_CF_BENCHMARKS'};
}
export async function fetchCryptoSignals({fetcher=fetch,now=Date.now(),symbols=['ETH','SOL','XRP','DOGE','ADA'],runSimulation=true}={}){
 const all=await Promise.all(symbols.filter(x=>candidates[x]).map(async symbol=>{
   const [s,m]=await Promise.allSettled([
    spotMomentum(fetcher,symbol,now),
    // Query MARKET listings directly. Nested /events can temporarily contain
    // only an expiring contract and cause false "no matched contract" labels.
    json(fetcher,`${KALSHI}/markets?series_ticker=KX${symbol}15M&status=open&limit=30`)
   ]);
   const spot=s.status==='fulfilled'?s.value:[],consensus=cryptoConsensus(spot,{symbol,now,minSources:5});
   const technical=spot.find(x=>x.source==='coinbase'&&x.indicators?.status==='OK')?.indicators||spot.find(x=>x.indicators?.status==='OK')?.indicators||null;
   const regime=assessCryptoRegime(consensus,technical);
   let sourceMarkets=m.status==='fulfilled'&&Array.isArray(m.value.markets)?m.value.markets:[];
   if(!sourceMarkets.length){
     try{
       const events=await json(fetcher,`${KALSHI}/events?series_ticker=KX${symbol}15M&status=open&limit=10&with_nested_markets=true`);
       sourceMarkets=(events.events||[]).flatMap(e=>e.markets||[]);
     }catch{/* An unavailable series is not a speculative authorization. */}
   }
   const markets=sourceMarkets.map(k=>({
    ticker:k.ticker,seriesTicker:`KX${symbol}15M`,symbol,status:k.status,
    rulesPrimary:k.rules_primary||'',closeTime:k.close_time,
    floorStrike:k.floor_strike==null?null:Number(k.floor_strike),
    yesAsk:kalshiPrice(k.yes_ask_dollars,k.yes_ask),noAsk:kalshiPrice(k.no_ask_dollars,k.no_ask),
    yesDepth:kalshiDepth(k.yes_ask_size_fp,k.yes_ask_size),
    noDepth:kalshiDepth(k.no_ask_size_fp,k.no_ask_size),
    observedAt:new Date(now).toISOString()
   }));
   const available=markets.filter(x=>['open','active'].includes(x.status)&&
       Date.parse(x.closeTime)-now>20000&&
       ((Number(x.yesAsk)>0&&Number(x.yesAsk)<1)||
        (Number(x.noAsk)>0&&Number(x.noAsk)<1)))
     .sort((a,b)=>Date.parse(a.closeTime)-Date.parse(b.closeTime));
   const market=available[0]||null;
   // Kalshi publishes the official CF Benchmarks opening target for an
   // active 15-minute contract. Prefer it over inferred spot candle opens.
   const strike=Number(market?.floorStrike);
   const liveSpots=spot.map(x=>Number(x.last)).filter(x=>Number.isFinite(x)&&x>0)
      .sort((a,b)=>a-b);
   const reference=market&&strike>0&&Number.isFinite(strike)&&liveSpots.length>=5?
     {referencePrice:strike,spotPrice:liveSpots[Math.floor(liveSpots.length/2)],
       sourceCount:liveSpots.length,source:'KALSHI_OFFICIAL_CF_OPENING_TARGET',
       exactBenchmarkReference:true}:
     (market?calculateCryptoWindowReference(spot,market.closeTime):null);
   const model=runSimulation&&reference&&consensus.allocationFraction>0?
     runCryptoMonteCarlo({symbol,spotPrice:reference.spotPrice,
      referencePrice:reference.referencePrice,
      minutesRemaining:(Date.parse(market.closeTime)-now)/60000,
      volatilityPct:technical?.realizedVolatilityPct??.35,
      observedAt:new Date(now).toISOString(),now,trials:5000}):null;
   // A public quote and a historical direction ARE actionable for a person
   // to review, but do not by themselves prove a profitable automated order.
   const signalDirection=consensus.direction;
   // Historical RSI/MACD are secondary observations. A verified 5-of-7
   // independent spot consensus remains the primary direction signal.
   const tradeDirection=signalDirection;
   const manualSide=market&&(tradeDirection==='UP'?'yes':tradeDirection==='DOWN'?'no':null);
   return {symbol,direction:tradeDirection,sources:consensus.sources,
    technical,regime:regime.regime,signalStrength:regime.signalStrength,forecastCalibrated:false,
    agreeingSources:consensus.agreeingSources,agreement:consensus.agreement,
    allocationFraction:consensus.allocationFraction,totalSupportedSources:7,
    model,reference,modeledWinProbability:model?.status==='ESTIMATED'?
      (tradeDirection==='UP'?model.lowerYesProbability:1-model.upperYesProbability):null,
    spreadPct:consensus.spreadPct??null,spotPrice:consensus.medianPrice??null,
    spotFeeds:consensus.observations.map(x=>({source:x.source,returnPct:x.returnPct})),
    missingSources:spot.missingSources||[],
    marketTicker:market?.ticker||null,market:market||null,yesAsk:market?.yesAsk??null,noAsk:market?.noAsk??null,
    closeTime:market?.closeTime||null,
    manualSide,manualReviewAvailable:Boolean(manualSide),signalIsForecast:false,
    allowed:false,eligibleForAutomation:false,
    reason:!market?'NO_MATCHING_ACTIVE_KALSHI_CONTRACT':'INDEPENDENT_PROBABILITY_NOT_ESTABLISHED',
    status:!market?'NO_OPEN_MATCHING_KALSHI_MARKET':consensus.reason,
    updatedAt:new Date(Math.abs(Date.now()-now)<120000?Date.now():now).toISOString()};
 }));
