   strategy:probabilitySource==='CRYPTO_SCENARIO_PROXY'?'CRYPTO_DIRECTIONAL_CONSENSUS':'LIVE_SPORTS_VALUE',
   ticker:market.ticker,side,contracts:count,limitPrice:px,feePerContract:fee,
