crypto_final_consensus.mjs:
/** Last-second independent executable-market price votes.
 * Live bid/ask snapshots compare seven venues to Kalshi's published CF target.
 * These votes confirm price level, not a guarantee of settlement.
 */
const venueNames=['coinbase','kraken','bitstamp','gemini','okx','kucoin','bitfinex'];
const symbols=new Set(['ETH','SOL','XRP','DOGE','ADA']);
const numeric=x=>x==null||x===''?NaN:Number(x);
const pOk=x=>Number.isFinite(x)&&x>0;
const quoteUrl=(venue,symbol)=>{
 const pair=symbol;
 const low=symbol.toLowerCase();
 return {
  coinbase:`https://api.exchange.coinbase.com/products/${symbol}-USD/ticker`,
  kraken:`https://api.kraken.com/0/public/Ticker?pair=${pair}USD`,
  bitstamp:`https://www.bitstamp.net/api/v2/ticker/${low}usd/`,
  gemini:`https://api.gemini.com/v1/pubticker/${low}usd`,
  okx:`https://www.okx.com/api/v5/market/ticker?instId=${symbol}-USDT`,
  kucoin:`https://api.kucoin.com/api/v1/market/orderbook/level1?symbol=${symbol}-USDT`,
  bitfinex:`https://api-pub.bitfinex.com/v2/ticker/t${symbol}USD`
 }[venue];
};
function readBidAsk(venue,j){
 let bid,ask,timestamp=null;
 switch(venue){
  case 'coinbase':
   bid=j?.bid;ask=j?.ask;timestamp=Date.parse(j?.time||'');break;
  case 'kraken':{
   const value=Object.values(j?.result||{}).find(x=>Array.isArray(x?.a)&&Array.isArray(x?.b));
   if(j?.error?.length||!value)return null;
   bid=value.b[0];ask=value.a[0];break;
  }
  case 'bitstamp':
   bid=j?.bid;ask=j?.ask;timestamp=numeric(j?.timestamp)*1000;break;
  case 'gemini':
   bid=j?.bid;ask=j?.ask;break;
  case 'okx':
   if(j?.code!=='0')return null;
   bid=j?.data?.[0]?.bidPx;ask=j?.data?.[0]?.askPx;
   timestamp=numeric(j?.data?.[0]?.ts);break;
  case 'kucoin':
   if(j?.code!=='200000')return null;
   bid=j?.data?.bestBid;ask=j?.data?.bestAsk;
   timestamp=numeric(j?.data?.time);break;
  case 'bitfinex':
   bid=j?.[0];ask=j?.[2];break;
  default:return null;
 }
 bid=numeric(bid);ask=numeric(ask);
 if(!pOk(bid)||!pOk(ask)||ask<bid||ask/bid>1.015)return null;
 return {price:(bid+ask)/2,timestamp};
}
export async function fetchFinalCryptoConsensus({fetcher=fetch,symbol,ticker,
 referencePrice,now=Date.now(),minMovePct=.005}={}){
 const invalid={symbol,marketTicker:ticker,direction:'UNKNOWN',agreeingSources:0,
   allocationFraction:0,observedSources:0,updatedAt:new Date(now).toISOString()};
 const ref=numeric(referencePrice);
 if(!symbols.has(symbol)||!pOk(ref)||typeof ticker!=='string'||
    !ticker.startsWith('KX'+symbol+'15M-'))return invalid;
 const settled=await Promise.allSettled(venueNames.map(async source=>{
   const response=await fetcher(quoteUrl(source,symbol),{method:'GET',redirect:'error',
     signal:typeof AbortSignal==='undefined'?undefined:AbortSignal.timeout(2500)});
   if(!response?.ok)throw Error('Spot quote unavailable');
   const parsed=readBidAsk(source,await response.json());
   if(!parsed)throw Error('Invalid quote');
   const age=now-parsed.timestamp;
   if(parsed.timestamp!=null&&(!Number.isFinite(age)||age< -10000||age>30000))
     throw Error('Stale provider quote');
   return {source,price:parsed.price};
 }));
 const rows=settled.filter(r=>r.status==='fulfilled').map(r=>r.value);
 if(rows.length<5)return {...invalid,observedSources:rows.length};
 const sorted=rows.map(x=>x.price).sort((a,b)=>a-b);
 const median=sorted[Math.floor(sorted.length/2)];
 const sane=rows.filter(x=>Math.abs(x.price/median-1)<=.01);
 if(sane.length<5)return {...invalid,observedSources:sane.length};
 const bound=minMovePct/100;
 const up=sane.filter(x=>x.price/ref-1>bound).length;
 const down=sane.filter(x=>x.price/ref-1< -bound).length;
 const agree=Math.max(up,down),direction=agree>=5?(up>down?'UP':'DOWN'):'UNKNOWN';
 return {symbol,marketTicker:ticker,direction,
   agreeingSources:direction==='UNKNOWN'?0:agree,observedSources:sane.length,
   allocationFraction:agree>=7?.4:agree===6?.3:agree===5?.2:0,
   updatedAt:new Date(now).toISOString(),
   source:'SEVEN_LIVE_SPOT_BID_ASK_LEVELS_VS_OFFICIAL_KALSHI_STRIKE',
   referencePrice:ref,spotMedianPrice:median,
   observations:sane.map(x=>({source:x.source,price:x.price}))};
}

sports_allocation.mjs:
import {seeded} from './engine.mjs';

const specs=Object.freeze({
 NFL:{periods:[4],maxClock:600,minLead:14,leadSpan:21,scoreSigma:3.0},
 CFB:{periods:[4],maxClock:600,minLead:14,leadSpan:21,scoreSigma:3.0},
 NBA:{periods:[4],maxClock:360,minLead:12,leadSpan:22,scoreSigma:2.5},
 WNBA:{periods:[4],maxClock:300,minLead:10,leadSpan:18,scoreSigma:2.0},
 CBB:{periods:[2],maxClock:360,minLead:12,leadSpan:22,scoreSigma:2.5},
 NHL:{periods:[3],maxClock:600,minLead:2,leadSpan:3,scoreSigma:.35},
 EPL:{periods:[2],maxClock:900,minLead:2,leadSpan:3,scoreSigma:.4},
 MLS:{periods:[2],maxClock:900,minLead:2,leadSpan:3,scoreSigma:.4},
 MLB:{periods:[8,9,10,11,12,13,14,15],maxClock:0,minLead:3,leadSpan:4,scoreSigma:1.0}
});
const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
const good=n=>Number.isFinite(n)&&n>=0;
const normal=rng=>Math.sqrt(-2*Math.log(Math.max(1e-9,rng())))*Math.cos(2*Math.PI*rng());

/** Score/time are the two sports ENTRY screens; this is a monotone tier policy. */
export function sportsLeadTier({sport,period,lead,clockSeconds}={}){
 const rule=specs[sport],left=Number(clockSeconds),difference=Number(lead);
 const periodOk=rule&&(sport==='MLB'?Number(period)>=8:rule.periods.includes(Number(period)));
 if(!rule||!periodOk||!good(left)||left>rule.maxClock||
    !good(difference)||difference<rule.minLead)return {eligible:false,maxAllocationFraction:0,reason:'LEAD_OR_GAME_TIME_NOT_QUALIFIED'};
 const timeStrength=rule.maxClock===0?1:clamp(1-left/rule.maxClock);
 const leadStrength=clamp((difference-rule.minLead)/rule.leadSpan);
 const strength=(timeStrength+leadStrength)/2;
 const maxAllocationFraction=strength>=.75?.50:strength>=.5?.35:strength>=.25?.20:.10;
 return {eligible:true,sport,period,clockSeconds:left,lead:difference,leadStrength,timeStrength,
   strength,maxAllocationFraction,reason:'LATE_GAME_COMMANDING_LEAD'};
}

/** Monte Carlo only reduces/chooses exposure; it never invents entry eligibility. */
export function monteCarloLateGameAllocation({sport,period,lead,clockSeconds,bankroll,seed=17,trials=3000}={}){
 const tier=sportsLeadTier({sport,period,lead,clockSeconds}),cash=Number(bankroll);
 if(!tier.eligible||!good(cash)||cash<=0)return {...tier,eligible:false,allocationFraction:0};
 const rule=specs[sport],rng=seeded(seed);
 const n=Math.max(2500,Math.min(15000,Math.floor(trials)||3000));
 let wins=0;
 for(let i=0;i<n;i++)if(Number(lead)+normal(rng)*rule.scoreSigma*Math.sqrt(clockSeconds/60)>0)wins++;
 const scenarioSurvival=wins/n;
 const allocationFraction=tier.maxAllocationFraction*(.70+.30*scenarioSurvival);
 return {...tier,trials:n,scenarioSurvival,modeledProbabilityIsEntryGate:false,
  allocationFraction,allocatedDollars:cash*allocationFraction};
}

/** FOK liquidity/price uncertainty changes size, not the confirmed score result. */
export function monteCarloOverAllocation({bankroll,price,depth,seed=17,trials=3000}={}){
 const cash=Number(bankroll),ask=Number(price),liquidity=Number(depth);
 if(!good(cash)||cash<=0||!(ask>0&&ask<1)||!good(liquidity)||liquidity<1)
  return {allocationFraction:0,trials:0,modeledProbabilityIsEntryGate:false};
 const rng=seeded(seed),n=Math.max(2500,Math.min(15000,Math.floor(trials)||3000));
 const desiredContracts=Math.floor(.80*cash/ask);
 let viable=0;
 for(let i=0;i<n;i++){
   const possible=Math.floor(liquidity*(.65+.5*rng()));
   if(possible>=desiredContracts)viable++;
 }
 const allocationFraction=.75+.05*viable/n;
 return {allocationFraction,trials:n,modeledProbabilityIsEntryGate:false,
  scenarioLiquiditySuccessRate:viable/n,allocatedDollars:cash*allocationFraction};
}

/** A live scoreboard lead/time qualifies the strategy; Monte Carlo only sizes it.
 * The conditional payout check is NOT a forecast or guaranteed net return.
 */
export function planLateGameOrder({game,market,bankroll,feePerContract,holdings,now=Date.now()}={}){
 const deny=reason=>({allowed:false,reason,strategy:'LATE_GAME_LEAD'});
 const home=Number(game?.homeScore),away=Number(game?.awayScore);
 const leading=Math.abs(home-away);
 if(!Number.isFinite(home)||!Number.isFinite(away)||home<0||away<0) return deny('SCORE_UNVERIFIED');
 const sizing=monteCarloLateGameAllocation({sport:game?.sport,period:game?.period,
   clockSeconds:game?.clockSeconds,lead:leading,bankroll,seed:29});
 if(!sizing.eligible)return deny('LEAD_OR_GAME_TIME_NOT_QUALIFIED');
 const cash=Number(bankroll),px=Number(market?.yesAsk),depth=Number(market?.yesDepth),fee=Number(feePerContract);
 const observedAge=now-Date.parse(market?.observedAt||'');
 if(!['active','open'].includes(market?.status)||!good(observedAge)||observedAge>3000)
  return deny('MARKET_NOT_EXECUTABLE_OR_STALE');
 if(!(px>0&&px<1)||!good(depth)||depth<1||!good(fee)||!good(cash)||cash<=0)
  return deny('PRICE_OR_CASH_UNVERIFIED');
 if(!Array.isArray(holdings))return deny('POSITIONS_UNVERIFIED');
 if(holdings.some(p=>p.ticker===market.ticker&&Number(p.position)!==0))return deny('EXISTING_MARKET_EXPOSURE');
 const unit=px+fee;
 if(!(1-unit>1e-9))return deny('NO_PROFIT_IF_CONTRACT_WINS');
 const budget=Math.min(cash,cash*sizing.allocationFraction);
 const contracts=Math.min(10000,Math.floor(depth),Math.floor(budget/unit));
 if(contracts<1)return deny('INSUFFICIENT_BANKROLL_OR_DEPTH');
 return {allowed:true,strategy:'LATE_GAME_LEAD',reason:'SCORE_AND_CLOCK_ELIGIBLE',
  ticker:market.ticker,side:'yes',contracts,limitPrice:px,feePerContract:fee,
  estimatedFeesDollars:Number((contracts*fee).toFixed(4)),
  estimatedMaxDebitDollars:Number((contracts*unit).toFixed(4)),
  modeledWinProbability:null,modeledLossFrequency:null,modeledProbabilityIsEntryGate:false,
  scenarioSurvival:sizing.scenarioSurvival,allocationFraction:sizing.allocationFraction,
  maximumAllocationFraction:sizing.maxAllocationFraction,
  netIfWinDollars:Number((contracts*(1-unit)).toFixed(4)),
  confidenceBasis:'LEAD_AND_TIME_ONLY',allocationBasis:'MONTE_CARLO_SIZING_ONLY'};
}

research_crawlers.mjs:
/** Research-only public page crawler pool. Adapted LegalWhat StarTrekCrawler's
 * bounded GET and public link/text extraction; zero Firecrawl requests.
 * Crawler output is NEVER used as authenticated Kalshi price/settlement evidence.
 */
const PUBLIC_HOSTS=new Set(['www.espn.com','www.kalshi.com','kalshi.com',
 'help.kalshi.com','docs.kalshi.com','www.cftc.gov']);
const limits=Object.freeze({'legalwhat-direct':{max:36,window:60000},
 'jina-reader':{max:12,window:60000},
 'markdown-new':{max:400,window:86400000},
 'crawl4ai-cloud':{max:75,window:86400000}});
const catalog=['legalwhat-direct','jina-reader','markdown-new','crawl4ai-cloud'];
const stripMarkup=s=>s.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ')
 .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ')
 .replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
const parsePublicUrl=url=>{
 let u;
 try{u=new URL(url)}catch{throw Error('Invalid public source URL')}
 if(u.protocol!=='https:'||!PUBLIC_HOSTS.has(u.hostname)||u.port||
    u.username||u.password||u.pathname.startsWith('/api/')||
    /\/(?:trade-api|portfolio|orders|account|balance|private)\b/i.test(u.pathname))throw Error('Public source not approved');
 u.hash='';return u;
};
export function makeResearchCrawlerPool({fetcher=fetch,env=process.env,now=Date.now}={}){
 let ordinal=0;const events=new Map();
 const stats=new Map(catalog.map(name=>[name,{successes:0,failures:0,lastSucceeded:null,lastFailure:null,requests:[]}]));
 const configured=name=>name!=='crawl4ai-cloud'||Boolean(env.CRAWL4AI_KEY);
 const status=()=>catalog.map(name=>{
   const x=stats.get(name);return {name,configured:configured(name),successes:x.successes,
     failures:x.failures,lastSucceeded:x.lastSucceeded,lastFailure:x.lastFailure,
     limits:{...limits[name]}};});
 const checkQuota=(name,ts)=>{
   const x=stats.get(name),lim=limits[name];
   x.requests=x.requests.filter(t=>ts-t<lim.window);
   return x.requests.length<lim.max&&!(x.lastFailure!=null&&ts-x.lastFailure<20000);
 };
 async function requestText(url,opts={}){
   const response=await fetcher(url,{...opts,redirect:'error',signal:AbortSignal.timeout(7500)});
   if(!response?.ok)throw Error('Crawler provider rejected request');
   const body=await response.text();
   if(typeof body!=='string'||body.length<15||body.length>3000000)throw Error('Crawler response invalid');
   return body.slice(0,70000);
 }
 async function provider(name,url){
   if(name==='legalwhat-direct'){
     // LegalWhat StarTrekCrawler's public fetch / bounded HTML extraction pattern.
     const raw=await requestText(url.toString(),{method:'GET',headers:{accept:'text/html,text/markdown'}});
     const content=raw.includes('<html')||raw.includes('<body')?stripMarkup(raw):raw;
     if(content.length<15)throw Error('Empty public document');
     return content.slice(0,40000);
   }
   if(name==='jina-reader')return requestText('https://r.jina.ai/'+url.toString(),{
     method:'GET',headers:{accept:'text/markdown'}});
   if(name==='markdown-new')return requestText('https://markdown.new/'+url.toString(),{
     method:'GET',headers:{accept:'text/markdown'}});
   if(name==='crawl4ai-cloud'){
     if(!env.CRAWL4AI_KEY)throw Error('Crawl4AI not configured');
     const result=await fetcher('https://api.crawl4ai.com/scrape',{
       method:'POST',redirect:'error',signal:AbortSignal.timeout(7500),
       headers:{authorization:'Bearer '+env.CRAWL4AI_KEY,'content-type':'application/json'},
       body:JSON.stringify({url:url.toString()})});
     if(!result?.ok)throw Error('Crawl4AI did not return a usable result');
     const response=await result.json();
     const raw=response?.markdown||response?.data?.markdown;
     if(typeof raw!=='string'||raw.length<15)return (()=>{throw Error('Crawl4AI content unavailable')})();
     return raw.slice(0,40000);
   }
   throw Error('Unknown crawler provider');
 }
 return {status,async get(target){
    const url=parsePublicUrl(target),ts=now(),start=ordinal++%catalog.length;
    for(let i=0;i<catalog.length;i++){
      const name=catalog[(start+i)%catalog.length];
      if(!configured(name)||!checkQuota(name,ts))continue;
      const x=stats.get(name);x.requests.push(ts);
      try{
        const content=await provider(name,url);
        x.successes++;x.lastSucceeded=now();
        return {provider:name,url:url.toString(),content,observedAt:new Date(Date.now()).toISOString(),
          executionApproved:false,authority:'UNVERIFIED_CONTEXT_ONLY'};
      }catch{x.failures++;x.lastFailure=now();}
    }
    throw Error('No public research crawler available');
 }};
}

